Given twice continuously differentiable functions   $\ph:\R^n\to \R$ and  $\Phi:\R^n\to \R^m$,  a convex polyhedral set  $\Th$ in $\R^n$, and a convex piecewise linear-quadratic (CPLQ) function $g:\R^m\to \oR$,
 we aim to present a local convergence analysis of the ALM for  the composite optimization problem 
\begin{equation}\label{comp}
\mbox{minimize}\;\;\ph(x)+g\big(\Phi(x)\big)\quad \mbox{subject to}\;\; x\in \Th.
\end{equation} 


The augmented Lagrangian $\L:\R^n\times \R^m\times (0,\infty)\to \R$ associated with the composite problem \eqref{comp} is defined  by 
\begin{equation}\label{aug}
\L(x,\lm,\rho):=\ph(x)+e_{ {1}/{\rho}} g \big(\Phi(x)+\rho^{-1}\lm\big)-\sm\rho^{-1}\|\lm\|^2
\end{equation}
with $e_{1/\rho} g$ signifying  the Moreau envelope of   $g$, given  by 
\begin{equation*}\label{Menv}
e_{1/\rho} g(y):=\inf_{z\in \R^m}\big\{g(z)+\frac{\rho}{2}\|y-z\|^2\big\}, \quad y\in \R^m.
\end{equation*}
It is well-known that the augmented Lagrangian $\L$ is continuously differentiable with respect to both $x$ and $\lm$ and is nondecreasing with the respect to $\rho$, the {\em penalty} parameter of the augmented Lagrangian. 
At  each iteration for a given pair $(\lm,\rho)\in \R^m\times (0,\infty)$,  our proposed  ALM for  the  composite problem \eqref{comp}
requires solving the {\em partially} augmented problem 
\begin{equation}\label{augp}
\mini \L(x, \lm, \rho)\quad \mbox{subject to}\;\; x\in \Th.
\end{equation} 


In this section, we first briefly review basic constructions of variational analysis and generalized differentiation employed in the paper. In what follows,    we 
 denote by $\B$ the closed unit ball in the space in question and by $\B_r(x):=x+r\B$ the closed ball centered at $x$ with radius $r>0$. 
 In the  product space $\R^n\times \R^m$, we use the norm $\|(w,u)\|=\sqrt{\|w\|^2+\|u\|^2}$ for any $(w,u)\in \R^n\times \R^m$.
 Given a nonempty set $C\subset\R^n$, the symbols $\inte C$,  $\cone C$, and $\span C$ signify its interior, conic hull, and the   linear space generated by  $C$, respectively. 
 For any set $C$ in $\R^n$, its indicator function is defined by $\dd_C(x)=0$ for $x\in C$ and $\dd_C(x)=\infty$ otherwise. We denote
 by $P_C$ the projection mapping onto $C$ and  by $\dist(x,C)$  the distance between $x\in \R^n$ and a set $C$.
 For a vector $w\in \R^n$, the subspace $\{tw |\, t\in \R\}$ is denoted by $[w]$. 
We write $x(t)=o(t)$ with $x(t)\in \R^n$ and $t>0$ to mean that ${\|x(t)\|}/{t}$ goes to $0$ as $t\dn 0$.
Finally, we denote by $\R_+$ (respectively,  $\R_-$) the set of non-negative (respectively, non-positive) real numbers.
For an $n\times m$ matrix $A$, we denote by $\ker A$ and $\rge A$ its null and range spaces, respectively.


A sequence    $\{C^k\b$ of subsets in $\R^n$ is called convergent to a set $C\subset\R^n$ as $k\to \infty$ if $C$ is closed and
\begin{equation*}
\lim_{k\to \infty}{\rm dist}(w,C^k)={\rm dist}(w,C)\;\mbox{ for all }\;w\in\R^n.
\end{equation*}
Given a nonempty set $C\subset\R^n$ with $\ox\in C$, the  tangent cone $T_ C(\ox)$ to $C$ at $\ox$ is defined by
\begin{equation*}\label{2.5}
T_C(\ox)=\big\{w\in\R^n|\;\exists\,t_k{\dn}0,\;\;w_k\to w\;\;\mbox{ as }\;k\to\infty\;\;\mbox{with}\;\;\ox+t_kw_k\in C\big\}.
\end{equation*}
When $C$ is convex, the  {normal cone} to $C$ at $\ox\in C$ in the sense of convex analysis  is given by
\begin{equation*}
N_C(\ox)=\big\{v\in\R^n\;\big|\; \la v,x-\ox\ra\le 0\quad \mbox{for all}\;\; x\in C\big\}.
\end{equation*}
For a convex  function $f:\R^n \to \oR:=(-\infty,\infty]$  with $\ox\in \dom f$, its   subdifferential at $\ox$   is defined  by 
\begin{equation*}\label{sub}
\partial f(\ox)=\big\{v\in\R^n\;\big|\;  \la v,x-\ox\ra\le f(x)-f(\ox)\;\;\mbox{for all}\;x\in \R^n\big\}.
\end{equation*}


A sequence $\{f^k\b$ of functions $f^k:\R^n\to \oR$ is said to {\em epi-converge} to a function $f:\R^n\to [-\infty,\infty]$ if we have $\epi f^k\to \epi f$ as $k\to \infty$.
We denote by $f^k\overset {\ss \mbox{e}}{\to} f$ the  epi-convergence of the sequence $\{f^k\b$ to $f$.
Given  a function  $f:\R^n \to \oR$ and  a point $\ox$ with $f(\ox)$ finite, the subderivative function $\d f(\ox)\colon\R^n\to[-\infty,\infty]$ is defined by
\begin{equation}\label{fsud}
{\mathrm d}f(\ox)(w)=\liminf_{\substack{
   t\dn 0 \\
  w'\to w
  }} {\frac{f(\ox+tw')-f(\ox)}{t}}.
\end{equation}
 The critical cone of $f$ at $\ox$ for $\ov$ with $(\ox,\ov)\in \gph \sub f$ is defined by 
$$
{K_f}(\ox,\ov)=\big\{w\in \R^n\big|\;\la\bar v,w\ra=\d f(\ox)(w)\big\}.
$$
When $f=\dd_C$, namely the indicator function of $C$, the critical cone of $\dd_C$ at $\ox$ for $\ov$ is denoted by $K_C(\ox,\ov)$. In this case, the above definition of the critical cone of a function 
boils down to  the well-known concept of the critical cone of a set (see \cite[page~109]{dr}), namely $K_C(\ox,\ov)=T_C(\ox)\cap [\ov]^\perp$.
Define the parametric  family of 
second-order difference quotients for $f$ at $\ox$ for $\ov\in \R^n$ by 
\begin{equation*}\label{lk01}
\Delta_t^2 f(\bar x , \ov)(w)=\dfrac{f(\ox+tw)-f(\ox)-t\langle \ov,\,w\rangle}{\frac{1}{2}t^2}\quad\quad\mbox{with}\;\;w\in \R^n, \;\;t>0.
\end{equation*}
If $f(\ox)$ is finite, then the {second subderivative} of $f$ at $\ox$ for $\ov$   is given by 
\begin{equation*}\label{ssd}
\d^2 f(\bar x , \ov)(w)= \liminf_{\substack{
   t\dn 0 \\
  w'\to w
  }} \Delta_t^2 f(\ox , \ov)(w'),\;\; w\in \R^n.
\end{equation*}
The second subderivative of $f$ at $\ox$ (without mention of $\ov$) is defined by 
\begin{equation}\label{ssud}
\d^2 f(\ox)(w)=\liminf_{\substack{t\dn 0\\
w'\to w}} \frac{f(\ox+tw')-f(\ox)-t\d f(\ox)(w')}{\sm t^2},\quad w\in \R^n.
\end{equation}
Following \cite[Definition~13.6]{rw}, a function $f:\R^n \to \oR$ is said to be {twice epi-differentiable} at $\bar x$ for $\ov\in\R^n$, with $f(\ox) $ finite, 
if the sets $\epi \Delta_t^2 f(\bar x , \ov)$ converge to $\epi \d^2 f(\bar x,\ov)$ as $t\downarrow 0$. 
In what follows, we refer to the second subderivative of $f$ at $\bar x$ for $\ov$ by the {\em second-order epi-derivative} of $f$ when it is twice epi-differentiable at   $\bar x$ for $\ov$.


Recall  that a function $g:\R^m\to \oR$ is called  piecewise linear-quadratic if $\dom g = \cup_{i=1}^{s} C_i$ with $s\in \N$ and $C_i $ being polyhedral convex  sets for $i = 1, \ldots, s$, and if $g$ has a representation of the form
\begin{equation} \label{PWLQ}
g(z) = \sm \langle A_i z ,z \rangle + \langle a_i ,z \rangle + \alpha_i  \quad \mbox{for all} \quad  z \in C_i,
\end{equation}
where $A_i$ is an $m \times m$ symmetric matrix, $a_i\in \R^m$, and $\alpha_i\in \R$ for all $i = 1, \cdots, s$. Take $\oz\in \dom g$ and define the {\em active} indices  of the domain of $g$ at $\oz$ by
\begin{equation}\label{act}
I(\oz)=\big \{i\in \{1,\ldots, m\} |\, \oz\in C_i\big \}.
\end{equation}
If in addition $g$ is convex, 
it follows   from \cite[page~487]{rw} that 
if  $\oz\in \dom g$, the subdifferential of $g$ at  $\oz$ can be calculated by 
\begin{equation}\label{sub}
\sub g(\oz)=\bigcap_{i\in I(\oz)} \big \{v\in \R^m |\, v-A_i \oz- a_i\in N_{ C_i}(\oz)\big \}.
\end{equation}


The   Karush-Kuhn-Tucker (KKT)   system associated with the composite problem \eqref{comp} is given by 
\begin{equation}\label{vs} 
0\in \nabla_x L(x,\lm)+N_\Th(x),\;\;\lm\in \sub g(\Phi(x)),
\end{equation}
where $L(x,\lm)= \ph(x)+\la \Phi(x),\lm\ra$ for any   $(x,\lm)\in \R^n\times \R^m$. 
Given a point $\ox\in\R^n$, we define the set of {  Lagrange multipliers} of the KKT system \eqref{vs} associated with $\ox$ by
\begin{equation}\label{laset}
\Lambda(\ox):=\big\{\lm\in\R^m\;\big|\; 0\in \nabla_x L(\ox,\lm)+N_\Th(\ox),\;\lm\in \sub g(\Phi(\ox))\big\}.
\end{equation}
If  $(\ox,\olm)$ is a solution to the KKT  system \eqref{vs},   we clearly have   $\olm\in\Lambda(\ox)$.
 Given  a solution $(\ox,\olm)$  to \eqref{vs}, the second-order sufficient condition (SOSC)
for the composite problem \eqref{comp} at $(\ox,\olm)$ is formulated by 
\begin{equation}\label{sosc}
\langle\nabla_{xx}^2L(\bar x,\olm)w,w\rangle+\d^2g (\Phi(\bar x),\olm) (\nabla \Phi(\ox)w )>0\quad \mbox{for all }\; w\in \D\setminus\{0\},
\end{equation}
where the convex cone $\D$ is defined by 
 \begin{equation}\label{coned}
 \D:=K_\Th\big(\ox,-\nabla_x L(\ox,\olm)\big)\cap \big\{w\in \R^n\big|\; \nabla \Phi(\ox)w\in K_g \big(\Phi(\ox),\olm \big)\big\}.
 \end{equation}


a result, obtained recently in \cite{s20}, showing that it yields an error bound estimate for the KKT system \eqref{vs}, which is central to our   local convergence analysis  in this paper. To this end,  recall that, given a constant $r>0$,    the proximal mapping of  a convex function $g:\R^m\to \oR$ is defined by 
\begin{equation*}\label{pr}
{\rm{prox}}_{rg}(x):=\underset{z\in \R^n}{\argmin} \big\{g(z)+\rsm\|x-z\|^2\big\},\quad x\in\R^m.
\end{equation*}
In what follows, when $r=1$, the proximal mapping of $g$ will be denoted by ${\rm{prox}_g}$. For such a convex function, 
it is known that for any $x\in \R^m$ we have 
\begin{equation}\label{prm}
{\rm{prox}}_{rg}(x)=\big(I+r\sub g\big)^{-1}(x) \quad \mbox{and}\quad \nabla e_rg(x)=\big(rI+(\sub g)^{-1}\big)^{-1}(x),
\end{equation}
where $I$ stands for the $m\times m$ identity matrix; see \cite[Proposition~12.19]{rw} and \cite[Theorem~2.26]{rw} for more details. 


A function $f:\R^n\to \oR$ is called fully amenable at $\ox\in \dom f$ if there is a neighborhood ${\cal O}$ of $\ox$ on which 
$f$ can be represented in the form $f=\psi\circ h$, where $\psi:\R^m\to \oR$ is a CPLQ function and   $h:\R^n\to \R^m$ is a ${\cal C}^2$ function, and the 
basic constraint qualification 
\begin{equation}\label{bcq}
N_{\ss \dom \psi}\big(h(\ox)\big)\cap \ker \nabla h(\ox)^*=\{0\}
\end{equation}
is satisfied. 


Recall that a function $f:\R^n\to \oR$ is called semidifferentiable at $\ox$ if it is finite at $\ox$ and the ``$\liminf$" in \eqref{fsud} is a ``$\lim$."
Furthermore, $f$ is said to be twice semidifferentiable at $\ox$ if it is semidifferentiable at $\ox$ and  the ``$\liminf$" in \eqref{ssud} is a ``$\lim$."


Recall that for  the current triple $(\xk, \lk,\rok)\in \R^n\times \R^m\times (0,\infty)$, the next primal iterate $\xkk$ in the ALM is computed as an optimal solution to 
  the subproblem
\begin{equation}\label{conv1}
\mini \L(x, \lk, \rok)\quad \mbox{subject to}\quad x\in \Th.
\end{equation} 
The next dual iterate $\lkk$ is  then calculated as the Lagrange multiplier associated with the optimal solution $\xkk$ to the subproblem \eqref{conv1}, namely  
\begin{equation}\label{lkk}
 \lkk := \nabla\menvk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big).
\end{equation}
 Since an optimal solution  $\xkk$ to the subproblem \eqref{conv1} always satisfies the {\em stationary}  condition
\begin{equation}\label{conv2}
0\in \nabla_x\L(\xkk, \lk, \rok) +N_\Th(\xkk),
\end{equation} 
and since it is often difficult to find an exact solution to \eqref{conv1} in practice, it is more convenient to look for a solution $\xkk$ satisfying the {\em approximate} stationary condition
\begin{equation}\label{xkk}
\dist\big(-\nabla_x\L(\xkk, \lk, \rok),N_\Th(\xkk)\big)\leq \ek,
\end{equation} 
where $\ek\geq 0$ is a   tolerance parameter.


\begin{Algorithm}[augmented Lagrangian method]\label{Alg1}
Choose $(x^0,\lambda^0)\in\Th\times \R^m$ and $\bar\rho>0$. Pick a sequence of tolerance parameters $\{\ek\c$ with $\ek>0$ for all $k$ and $\ek\to   0$ as $k\to\infty$ and a sequence of $\{\rok\c$ such that  $\rok\ge \bar\rho$ for all $k$ and set $k:=0$. Then
\begin{itemize}[noitemsep,topsep=0pt]
\item [{\rm (1)}] if $(\xk,\lk)$ satisfies a suitable termination criterion, stop;
\item[{\rm (2)}]  otherwise, choose  $\xkk$ such that  \eqref{xkk} holds and then update the Lagrange multiplier  $\lkk$ by \eqref{lkk};
\item[{\rm (3)}] set $k\leftarrow k+1$ and go to Step~1.
\end{itemize}
\end{Algorithm}

Thus, in the rest of this paper, we assume further that the  polyhedral convex set  $\Th$ has a representation of the form 
\begin{equation}\label{Th}
\Th:=\big\{x\in\R^n\,|\, Bx = b\big \},
\end{equation} 
where $B$ is a $s\times n$ matrix and $b$ is a vector in $\R^s$. Furthermore, our convergence analysis of the ALM  requires to consider the \textit{residual function} $R: \R^n\times \R^m \to \R$ of the KKT system \eqref{vs}, given by
\begin{equation}\label{res}
R(x, \lm) : =  \dist\big(-\nabla_x L(x, \lm), N_\Th(x)\big)+\big\|\Phi(x)-{\rm{prox}}_g\big(\Phi(x)+\lm\big)\big\|, \quad (x, \lm) \in \R^n\times \R^m.
\end{equation}


 convergence of generalized equations with non-isolated solutions. To this end, let  $\sigma:\R^n\times \R^m\to \R_+$ be a function that satisfies  the condition
 \begin{equation}\label{error}
 \sigma(x,\lm)=o\big(R(x,\lm)\big)\quad \mbox{as}\;\;(x,\lm)\to (\ox,\olm),
 \end{equation}
where $R$ is the residual function \eqref{res} and $(\ox,\olm)$ is a solution to the KKT system \eqref{vs}.

