\begin{Proposition}[second-order variational properties of CPLQ] \label{sop} Assume that $g:\R^m\to \oR$ is a CPLQ function with representation \eqref{PWLQ}
and that $\oz\in \dom g$ and $\ov\in \sub g(\oz)$. Set $\ov_i:=\ov -A_i \oz -a_i$ for all $i\in I(\oz)$. 
Then the following conditions hold:
 \begin{itemize}[noitemsep,topsep=0pt]
 \item [{\rm (a)}]   the critical cone of $g$ at $\oz$ for $\ov$ can be calculated by $K_g(\oz,\ov)=N_{\sub g(\oz)}(\ov)$. Moreover, we have 
\begin{equation}\label{cc2}
  \d^2 g(\oz , \ov ) (w)=\d^2 g(\oz)(w)+\dd_{K_g(\oz,\ov)}(w), \quad w\in \R^m.
\end{equation}
 \item [{\rm (b)}] the function $g$ is twice epi-differentiable at $\ox$ for $\ov$ and its second-order epi-derivative  at this point can be calculated by 
\begin{equation}\label{pwfor}
 \d^2 g(\oz , \ov ) (w)  
=\begin{cases}
\la A_i w, w\ra&\mbox{if}\;\; w\in {K}_{C_i}(\oz,\ov_i),\\
\infty&\mbox{otherwise}.
\end{cases}
\end{equation}
Moreover, we have 
\begin{equation}\label{domcr}
K_g(\oz,\ov)=\bigcup_{i\in I(\oz)} {K}_{C_i}(\oz,\ov_i).
\end{equation}
  \end{itemize}
\end{Proposition}

\begin{Theorem}[error bound via second-order optimality conditions]\label{sooc} 
 Assume that $(\ox,\olm)$ is a solution to the KKT system \eqref{vs}. If the SOSC \eqref{sosc} holds at $(\ox,\olm)$, then
 there are positive constants $\gg_1$ and $\kappa_1$ for which  the error bound estimate
\begin{equation}\label{subr3}
\|x-\ox\|+\dist\big(\lm,\Lambda(\ox)\big)\le\kappa_1\Big(\dist\big(-\nabla_x L(x,\lm),N_\Th(x)\big)+\| \Phi(x)-{\rm{prox}}_g\big(\lm+ \Phi(x)\big)\|\Big)
\end{equation}
holds for any $(x,\lm)\in\B_{\gg_1}(\ox,\olm)$.
 \end{Theorem}

\begin{Proposition}[properties of the augmented Lagrangian]\label{paug}
Assume that  $(x, \lm, \rho)\in \R^n\times \R^m\times (0, \infty)$ and $\ox\in \R^n$. Then the following conditions hold for the  augmented Lagrangian   \eqref{aug}:
\begin{enumerate}[noitemsep,topsep=0pt]
\item the function $x \mapsto \L(x, \lm, \rho)$ is $\mathcal{C}^1$ and fully amenable at $\ox$;
\item the function $\lm \mapsto \L(x, \lm, \rho)$ is concave;
\item the function $\rho \mapsto \L(x, \lm, \rho)$ is nondecreasing.
\end{enumerate}
\end{Proposition}

\begin{Proposition}[propagation of stationary conditions]\label{fopag}
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs}. Then for any $\rho>0$,  the following conditions are satisfied:
\begin{enumerate}[noitemsep,topsep=0pt]
\item we always have  $\L(\ox,\olm,\rho)=\ph(\ox)+g\big(\Phi(\ox)\big)$;
\item $\ox$ is a stationary point of the augmented  problem 
\begin{equation}\label{ap}
\mini\; \L(x,\olm,\rho)\quad \mbox{subject to}\;\; x\in \Th.
\end{equation}
\end{enumerate}
\end{Proposition}

\begin{Proposition}[quadratic growth condition for augmented Lagrangians]\label{2ndgr}
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and set $\ov:= \nabla_x L(\ox,\olm)$. Then for any $\rho>0$,  the following conditions are equivalent: 
\begin{enumerate}[noitemsep,topsep=0pt]
\item    there exists a constant $\bar\rho>0$ such that for any $\rho\ge\bar\rho$ the second-order condition 
\begin{equation}\label{eq26}
\d^2_x\L\big((\ox,\olm,\rho),\ov\big)(w)>0\;\mbox{ for all }\;w\in K_\Th (\ox,-\ov ) \setminus\{0\}
\end{equation}
holds;
 \item  there exist positive constants $\bar\rho$, $\gamma$, and $\ell$ such that for any $\rho\ge\bar \rho$, the quadratic growth condition 
 \begin{equation}\label{eq16}
\L(x,\olm,\rho)\ge \ph(\ox)+g\big(\Phi(\ox)\big)+\ell\| x-\bar x\|^2\quad \mbox{ for all }\;x\in\B_\gg (\ox)\cap \Th
\end{equation}
holds. 
\end{enumerate}
\end{Proposition}

\begin{Theorem}[second subderivatives of augmented Lagrangians]\label{ssc} 
Assume that  $(x, \lm, \rho)\in \R^n\times \R^m\times (0, \infty)$ and $\ox\in \R^n$. 
Then  the function $x\mapsto\L(x,\lm,\rho)$, defined via the augmented Lagrangian \eqref{aug}, is twice epi-differentiable at $\ox$ for $\ov:=\nabla_x \L(\ox,\lm,\rho)$ and its second-order epi-derivative 
can be calculated for any $w\in \R^n$ by
\begin{equation}\label{eq40}
\d^2_x\L\big((\ox,\lm,\rho),\ov\big)(w)=\big\langle \nabla^2_{xx}L(\ox,\mu)w,w\big\rangle+ e_{1/{2\rho}}\big(\d^2 g\big(\Phi(\ox)+\rho^{-1}(\lm-\mu),\mu\big)\big) \big(\nabla \Phi(\ox)w \big), 
\end{equation}
where $\mu=\nabla_x \big(e_{1/{\rho}}g\big)\big(\Phi(\ox)+\rho^{-1}\lm\big)$.
\end{Theorem}

\begin{proof}  Given $\rho>0$,  it follows from  the second equality in \eqref{prm} that $\mu\in \sub g\big(\Phi(\ox)+\rho^{-1}(\lm-\mu)\big)$. 
According to Proposition~\ref{sop}(b), the CPLQ function $g$ is twice epi-differentiable at $\Phi(\ox)+\rho^{-1}(\lm-\mu)$ for $\mu$. Appealing now 
to  \cite[Proposition~4.1]{hms20} tells us that    the   envelope function $e_{1/\rho} g$ is twice epi-differentiable at $\Phi(\ox)+\rho^{-1}\lm$ for $\mu$ and that 
\begin{equation}\label{more}
\d^2 (e_{1/\rho} g )\big(\Phi(\ox)+\rho^{-1}\lm,\mu\big)=e_{1/2\rho}\big(\d^2 g(\Phi(\ox)+\rho^{-1}(\lm-\mu),\mu)\big).
\end{equation}
By \eqref{pwfor}, the second-order epi-derivative of $g$ is CPLQ. This, combined with \eqref{more}, indicates that $ e_{1/2\rho}\big(\d^2 g(\Phi(\ox)+\rho^{-1}(\lm-\mu),\mu)\big)$
is finite on $\R^m$. Employing now \cite[Theorem~4.3]{r20}, we conclude that  $e_{1/\rho}g$ is twice semidifferentiable at $\Phi(\ox)+\rho^{-1}\lm$ and its second semiderivative 
coincides with its second-order epi-derivative, namely 
\begin{equation}\label{ssed}
\d^2\big(e_{1/\rho}g\big)\big(\Phi(\ox)+\rho^{-1}\lm\big)=\d^2 (e_{1/\rho} g )\big(\Phi(\ox)+\rho^{-1}\lm,\mu\big).
\end{equation}
This, together with the chain and sum rules for twice semidifferentiability, established in  \cite[Propositions~8.2(i) and 8.1]{mmstams}, 
shows that the mapping $x\mapsto\L(x,\lm,\rho)$ is twice semidifferentiable at $\ox$. Thus, by   \cite[Propositions~8.2(iii)]{mmstams}, the latter mapping is twice epi-differentiable at $\ox$ for $\ov$ and 
\begin{equation}\label{lss}
\d_x^2{\L}(\ox,\lm,\rho)(w)=\d^2_x\L\big((\ox,\lm,\rho),\ov\big)(w), \quad w\in \R^n.
\end{equation}
By  \cite[Propositions~8.2(i) and 8.1]{mmstams},  the second  semiderivative of $x\mapsto\L(x,\lm,\rho)$ at $\ox$ can be calculated for any $w\in \R^n$ by
\begin{eqnarray*}
\d_x^2{\L}(\ox,\lm,\rho)(w)&=&\d^2\ph(\ox)(w)+\big\la\mu,\nabla^2\Phi(\ox)(w,w)\big\ra+\d^2\big(e_{1/\rho} g\big)\big(\Phi(\ox)+\rho^{-1}\lm\big)\big(\nabla \Phi(\ox)w\big)\\
&=&\la\nabla^2\ph(\ox)w,w\ra+\big\la\mu,\nabla^2\Phi(\ox)(w,w)\big\ra+\d^2\big(e_{1/\rho} g\big)\big(\Phi(\ox)+\rho^{-1}\lm,\mu\big)\big(\nabla \Phi(\ox)w\big)\\
&=&\big\la\nabla_{xx}^2L(\ox,\mu)w,w\big\ra+e_{1/2\rho}\big(\d^2 g(\Phi(\ox)+\rho^{-1}(\lm-\mu),\mu)\big)\big(\nabla \Phi(\ox)w\big),
\end{eqnarray*}
where the second equality comes from \eqref{ssed} and the last one results from \eqref{more}. This together with \eqref{lss}
justifies \eqref{eq40} and hence completes the proof.
\end{proof}

\begin{Corollary}[second-order epi-derivatives] Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and set $\ov:= \nabla_x L(\ox,\olm)$. Then for any $\rho>0$,
the function $x\mapsto\L(x,\lm,\rho)$, defined via the augmented Lagrangian \eqref{aug}, is twice epi-differentiable at $\ox$ for $\ov $ and its second-order epi-derivative 
can be calculated for any $w\in \R^n$ by
\begin{equation}\label{eq402}
\d^2_x\L\big((\ox,\olm,\rho),\ov\big)(w)=\big\langle \nabla^2_{xx}L(\ox,\olm)w,w\big\rangle+ e_{1/{2\rho}}\big(\d^2 g\big(\Phi(\ox),\olm\big)\big) \big(\nabla \Phi(\ox)w \big).
\end{equation}
\end{Corollary}

\begin{Theorem}[characterizations of quadratic growth condition]\label{growth}
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and set $\ov:= \nabla_x L(\ox,\olm)$. Then the following conditions are equivalent: 
 \begin{enumerate}[noitemsep,topsep=0pt]
 \item  the SOSC \eqref{sosc} holds at $(\ox,\olm)$;
 \item   there exists a constant $\bar\rho>0$ such that for any $\rho\ge\bar\rho$ the second-order condition \eqref{eq26} is satisfied;
 \item there exist positive constants $\bar\rho$, $\gg$, and $\ell$ such that for any $\rho\ge\bar \rho$, the quadratic growth condition \eqref{eq16} 
holds.
\end{enumerate}
\end{Theorem}

\begin{Lemma}[second-order epi-derivatives of augmented Lagrangians] \label{usog}
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and set $\ov:= \nabla_x L(\ox,\olm)$. 
Then the following conditions are equivalent: 
 \begin{enumerate}[noitemsep,topsep=0pt]
 \item the  SOSC \eqref{sosc} holds at $(\ox,\olm)$;
 \item there exist positive constants $\bar\rho$, $\ell_1$, $\ve_1$ such that for all $\rho\ge\bar\rho$ and
all  $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ we have
\begin{equation}\label{eq44}
\d^2_x\L \big((\ox,\lm,\rho), \nabla_x L(\ox,\lm)\big)(w)\ge\ell_1\|w\|^2\;\mbox{ for all }\;w\in K_\Th\big(\ox, - \nabla_x L(\ox,\olm)\big).
\end{equation}
\end{enumerate}
\end{Lemma}

\begin{proof} The implication (b)$\implies$(a)   results directly from Theorem~\ref{growth}. To prove the opposite implication, assume that (a) holds. 
It follows from Theorem~\ref{growth} that there exists a constant $\bar\rho>0$ such that for all $\rho\ge\bar\rho$ the second-order condition \eqref{eq26} is satisfied. 
Recall from  \cite[Proposition~13.5]{rw} that  the second-order epi-derivative  is lower semicontinuous and positive homogenous of degree $2$. 
Thus the second-order condition  \eqref{eq26} is equivalent  to the existence of a constant $\ell_1>0$ such that the estimate 
\begin{equation}\label{eq41}
\d^2_x\L \big((\ox,\olm,\bar\rho),\ov \big)(w)=\big\langle \nabla^2_{xx}L(\ox,\olm)w, w\big\rangle+ e_{ {1}/{2\bar\rho}}\big(\d^2 g(\Phi(\ox),\olm)\big)(\nabla\Phi(\ox)w)\ge 2\ell_1
\end{equation}
holds for all $w\in \S\cap K_\Th(\ox, -\ov)$, where the equality in \eqref{eq41} comes from  \eqref{eq40}. We proceed now by proving the following claim:

{\bf Claim A.} {\em There exists an $\varepsilon_1>0$ such that for any $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ the estimate
\begin{equation}\label{clq2}
\d^2_x\L \big((\ox,\lm,\bar\rho), \nabla_x L(\ox,\lm) \big)(w)=\big\langle \nabla^2_{xx}L(\ox,\lm)w,w\big\rangle+ e_{ {1}/{2\bar\rho}}\big(\d^2 g(\Phi(\ox),\lm)\big)(\nabla\Phi(\ox)w)\ge \ell_1
\end{equation} 
 holds for all $w\in \S\cap K_\Th\big(\ox, -\nabla_x L(\ox,\lm)\big)$.}

  To furnish this claim, choose $\varepsilon_1\in (0, {\ell_1}/{\|\nabla^2\Phi(\ox)\|})$ if $\|\nabla^2\Phi(\ox)\|\neq 0$ and $\varepsilon_1 > 0$ otherwise
  and let $w\in \S$.
 Thus for all     $\lm\in \B_{\ve_1}(\olm)$, we obtain   
\begin{eqnarray}\label{clq3}
\big\langle \nabla^2_{xx}L(\ox,\lm)w, w\big\rangle &=& \big\langle \nabla^2_{xx}L(\ox,\olm)w, w\big\rangle+\big\langle\lm -\olm, \nabla^2  \Phi (\ox)(w, w)\big\rangle\nonumber\\
&\geq&\big\langle \nabla^2_{xx}L(\ox,\olm)w, w\big\rangle - \|\nabla^2\Phi(\ox)\|\cdot\|\lm - \olm\|\nonumber\\
&\geq&\big\langle \nabla^2_{xx}L(\ox,\olm)w, w\big\rangle - \ell_1.
\end{eqnarray}
Moreover, it follows from \eqref{cc2} that 
\begin{eqnarray}\label{clq4}
e_{ {1}/{2\bar\rho}}\big(\d^2 g(\Phi(\ox),\lm)\big)(\nabla\Phi(\ox)w)&=&\inf_{v\in \R^m}\big\{\d^2g\big(\Phi(\ox)\big)(v)+\delta_{K_g(\Phi(\ox), \lm)}(v)+\bar\rho\|v-\nabla\Phi(\ox)w\|^2\big\}\nonumber\\ 
&=& \inf_{v\in K_g(\Phi(\ox), \lm)}\big\{\d^2g \big(\Phi(\ox) \big)(v)+\bar\rho\|v-\nabla\Phi(\ox)w\|^2\big\}. 
\end{eqnarray}
Note that $\d^2g(\Phi(\ox))$ does not depend on $\lambda$. Shrinking $\ve_1$ if necessary and recalling that $\sub g\big(\Phi(\ox)\big)$ is a polyhedral convex set, we conclude from   Proposition~\ref{sop}(a) that  
the relationships 
\begin{equation*}
K_g(\Phi(\ox), \lm) = N_{\partial g(\Phi(\ox))}(\lm) \subset N_{\partial g(\Phi(\ox))}(\olm) = K_g(\Phi(\ox), \olm) 
\end{equation*} 
hold for all $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$.  These, together with  \eqref{clq4}, tell us  that for any $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ we have 
\begin{equation}\label{clq5}
e_{ {1}/{2\bar\rho}}\big(\d^2 g(\Phi(\ox),\lm)\big)(\nabla\Phi(\ox)w) \geq e_{ {1}/{2\bar\rho}}\big(\d^2 g(\Phi(\ox),\olm)\big)(\nabla\Phi(\ox)w).
\end{equation} 
 Combining \eqref{eq41}, \eqref{clq3}, and \eqref{clq5} verifies   \eqref{clq2} for all $w\in \S\cap K_\Th(\ox, -\ov)$ and   all $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$. 
 To justify \eqref{clq2} for all $w\in \S\cap  K_\Th \big(\ox, -\nabla_x L(\ox, \lm) \big)$, observe that by the  polyhedrality of $\Th$,   we can assume without loss of generality that 
 $$
 K_\Th \big(\ox, -\nabla_x L(\ox, \lm) \big)=N_{N_\Th(\ox)}\big(-\nabla_x L(\ox, \lm)\big) \subset N_{N_\Th(\ox)}\big(-\nabla_x L(\ox, \olm)\big) = K_\Th(\ox, -\ov)
 $$
  for all $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$. This clearly justifies Claim A. 

Using the positive homogeneity of the second-order epi-derivative yields \eqref{eq44} for $\rho = \bar\rho$ and for all $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$. Recall that the function $$\rho\mapsto e_{ {1}/{2\rho}}\big(\d^2 g(\Phi(\ox),\lm)\big)(\nabla\Phi(\ox)w)$$ is nondecreasing. So is the function $\rho \mapsto\d^2\L( (\ox, \lm, \rho), \nabla_x L(\ox, \lm))(w)$. This  
yields  \eqref{eq44}  for all $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ and all $\rho \geq \bar\rho$, and hence completes the   proof.
\end{proof}

\begin{Theorem}[uniform quadratic growth condition for augmented Lagrangians]\label{ugrowth}
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs}. Then the following conditions are equivalent:
 \begin{enumerate}[noitemsep,topsep=0pt]
 \item    the  SOSC \eqref{sosc} holds at $(\ox,\olm)$;
 \item there are positive constants $\bar\rho, \gamma, \varepsilon,\ell$ such that for all $\lm\in\Lambda(\ox)\cap\B_\varepsilon(\olm)$ and all $\rho\ge\bar\rho$  the uniform quadratic growth condition
\begin{equation}\label{eq14}
\L(x,\lm,\rho)\ge \ph(\ox)+g(\Phi(\ox))+\ell\| x-\ox\|^2\;\mbox{ for all }\;x\in\B_\gamma(\ox)\cap \Th
\end{equation}
is satisfied.
\end{enumerate}
\end{Theorem}

\begin{proof} The implication (b)$\implies$(a)   results directly from Theorem~\ref{growth}. To prove the opposite implication, assume that (a) holds. 
It follows from Lemma~\ref{usog} that there exist the positive constants $\ell_1$, $\varepsilon_1$, and $\bar\rho$  for which \eqref{eq44} is satisfied  for all 
 $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ and all $\rho\ge\bar\rho$. Using this and  Proposition~\ref{fopag}(a), 
 we deduce from \eqref{eq44} that for any $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$ there exists $\gamma_{\lm}>0$ for which we have 
\begin{equation}\label{eq22}
\L(x,\lm,\bar\rho)\ge \ph(\ox)+g(\Phi(\ox))+\dfrac{\ell_1}{2}\Vert x-\ox\Vert^2\;\textrm{ for all }\;x\in\B_{\gamma_\lm}(\ox)\cap \Th,
\end{equation}
where the constant $ {\ell_1}$ can be chosen the same for all the multipliers $\lm\in\Lambda(\ox)\cap\B_{\varepsilon_1}(\olm)$. The
latter results directly from the definition of the second subderivative. The radii of the balls centered at $\ox$ in \eqref{eq22}, however,  depend on $\lm$. We argue below that  a common radius can be chosen for all the multipliers $\lm\in\Lambda(\ox)$ that are sufficiently close to $\olm$. To this end, assume that 
$$
\tilde\B_{\varepsilon_1}(\olm)=\big\{\lm\in \R^m|\; \|\lm-\olm\|_1\le \ve_1\big\}
$$
where $\|\lm-\olm\|_1$ stands for $L_1$-norm of the vector $\lm-\olm$, namely the sum of the absolute values of the components of $\lm-\olm$. Clearly, we have $\tilde\B_{\varepsilon_1}(\olm)\subset \B_{\varepsilon_1}(\olm)$.  Define the function $\psi\colon\R^m\to\oR$ by
\begin{equation}\label{eq23}
\psi(\lm):=\sup_{x\in\big(\B_{\gamma_{\olm}}(\ox)\cap \Th\big)\setminus \{\ox\}}\frac{\ph(\ox)+g(\Phi(\ox))-\L(x,\lambda,\bar\rho)}{\Vert x-\ox\Vert^2}
+\delta_{\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm)} (\lambda),\quad\lm\in\R^m.
\end{equation}
By Proposition~\ref{paug}(b), the function $\lambda\mapsto\L(x,\lm,\bar\rho)$ is concave. This, combined with the convexity of the set $\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm)$, 
 guarantees  that $\psi$ in \eqref{eq23} is a convex function. Moreover, $\psi$ is lower semicontinuous since  the first term on the right-hand side of \eqref{eq23} is the pointwise supremum of a collection of continuous functions.
 Now we claim  that for any $\lm\in\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm)$ the value $\psi(\lm)$ is finite. To justify this claim, let $\lm\in\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm)$. If  $\gamma_\lm\ge\gamma_{\olm}$,  we conclude from    \eqref{eq22} that 
\begin{equation*}
\psi(\lm)\le\sup_{x\in \big(\B_{\gamma_{\lm}}(\ox)\cap \Th\big)\setminus \{\ox\}}\frac{\ph(\ox)+g(\Phi(\ox))-\L(x,\lm,\bar\rho)}{\Vert x-\ox\Vert^2}\le-\dfrac{\ell_1}{2},
\end{equation*}
which, in particular,   implies that $\psi(\olm)\le- {\ell_1}/{2}$. On the other hand, if $\gamma_\lm<\gamma_{\olm}$, we get  
\begin{eqnarray*}
 &&\psi(\lm) \le\\
&&  \max\left\{\sup_{x\in \big(\B_{\gamma_{\lm}}(\ox)\cap \Th\big)\setminus \{\ox\}}\frac{\ph(\ox)+g(\Phi(\ox))-\L(x,\lm,\bar\rho)}{\Vert x-\ox\Vert^2},\max_{\substack{\gamma_\lm\le\Vert x-\ox\Vert\le\gamma_{\olm}\\ x\in \Th}}\dfrac{\ph(\ox)+g(\Phi(\ox))-\L(x,\lm,\bar\rho)}{\Vert x-\ox\Vert^2}\right\}.
\end{eqnarray*}
By \eqref{eq22}, the first term inside the maximum is bounded above by  $- {\ell_1}/{2}$.  Also, the second term is finite since it is the maximum of a continuous function over a compact set. 
Combining these tells us that $\psi(\lm)$ is finite for all $\lm\in\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm)$, which  results in 
$$
\dom\psi=\Lambda(\ox)\cap \tilde\B_{\varepsilon_1}(\olm).
$$
Since both sets  $\Lambda(\ox)$ and $\tilde\B_{\varepsilon_1}(\olm)$ are polyhedral, $\dom\psi$ is   a compact polyhedral convex set.
Appealing now to   \cite[Theorem~2.35]{rw} ensures that  $\psi$ is continuous relative to its domain.  
Thus, we can find  $\varepsilon >0$ such that $\B_\varepsilon(\olm)\subset \tilde\B_{\varepsilon_1}(\olm)$   and that
\begin{equation*}
\psi(\lm)\leq \psi(\olm)+\frac{\ell_1}{4}\leq -\frac{\ell_1}{4}  
\end{equation*} 
for all $\lm \in \dom\psi\cap \B_\varepsilon(\olm)=\Lambda(\ox)\cap \B_\varepsilon(\olm)$. This, combined with the definition of $\psi$ in \eqref{eq23}, tells us that for 
all $x\in\B_{\gamma_{\olm}}(\ox)\cap \Th$ and all $\lm\in\Lambda(\ox)\cap\B_\varepsilon(\olm)$ we have 
\begin{equation}\label{eq25}
\L(x,\lm,\bar\rho)\ge \ph(\ox)+g(\Phi(\ox))+\frac{\ell_1}{4}\Vert x-\bar x\Vert^2.
\end{equation}
Remember that by  Proposition~\ref{paug}(c) we always have 
\begin{equation*}
\L(x,\lm,\rho)\ge\L(x,\lm,\bar\rho)\;\mbox{ for all}\;\;\rho\ge\bar\rho.
\end{equation*}
Combining this with \eqref{eq25} and setting $\ell:= {\ell_1}/{4}$ verify the uniform quadratic growth condition \eqref{eq14} and hence complete the proof.
\end{proof}

\begin{Proposition}[solvability of subproblems]\label{solv} 
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and let  the  SOSC \eqref{sosc} hold at $(\ox,\olm)$.
Then there exist positive constants      $\tau$ and $\hat\gamma\le \gg$  with $\gg$ taken from Theorem~{\rm \ref{ugrowth}}  such that for any $\rho\ge \bar\rho $ with $\bar\rho$ taken from Theorem~{\rm\ref{ugrowth}},
 the optimal solution mapping $S_\rho:\R^m\to \R^n$, defined by 
\begin{equation}\label{eq177}
S_\rho(\lambda):=\argmin\big\{\L(x,\lambda,\rho)\;\big|\; x\in\Th\cap\B_{\hat\gamma}(\ox)\big\}, \;\;\lm\in \R^m,
\end{equation}
enjoys the uniform  isolated calmness property 
\begin{equation}\label{pt9}
   S_\rho(\lambda) \subset\{\ox\} +\tau \Vert\lambda-\olm\Vert\B
\end{equation}
 and satisfies the condition $\emp \neq S_\rho(\lambda)\subset  \inte  \B_{\hat\gamma}(\ox)$ for all $\lm\in \B_{\hat\gamma/2\tau}(\olm)$.  
 \end{Proposition}

\begin{proof} Since the SOSC \eqref{sosc} is satisfied at $(\ox,\olm)$, it follows from Theorem~\ref{ugrowth}
that there exist positive constants $\bar\rho$, $\gg$, and $\ell$ such that for any $\rho\ge\bar \rho$, the uniform quadratic growth condition \eqref{eq14} holds for $\lm=\olm$. Moreover, 
by the twice differentiability of  $\Phi$  at $\ox$, we find some  constants $\hat\gamma\in(0,\gamma]$ and $\kappa_\Phi>0$ for which we have 
\begin{equation}\label{eq49}
\Vert\Phi(x)-\Phi(\ox)\Vert\le\kappa_\Phi\Vert x-\ox\Vert\;\textrm{ for all }\;x\in\B_{\hat\gamma}(\ox).
\end{equation}
Clearly,  the uniform quadratic growth condition \eqref{eq14} for $\lm=\olm$ indicates  that  $S_\rho(\olm)\cap \B_{\gamma}(\ox)=\{\ox\}$ for all $\rho\ge\bar\rho$. 
Define   the positive constant
\begin{equation}\label{eq21}
\tau:=\frac{\kappa_\Phi}{\ell}+\sqrt{\frac{\kappa_\Phi^2}{\ell^2}+\frac{1}{\ell\bar\rho}},
\end{equation}
and fix   $\lambda\in \B_{\hat\gamma/2\tau} (\olm)$ and $\rho\geq\bar\rho$.
Observe from the classical Weierstrass theorem that $S_\rho(\lm)\neq\emp$.   Assume that  $u\in S_\rho(\lambda)$.
By  Proposition~\ref{paug}(b),   the function $\lambda\mapsto\L(u,\lambda,\rho)$ is concave. 
By \cite[Theorem~2.26(b)]{rw}, we have 
\begin{equation}\label{ueq19}
\nabla_\lm\L(u, \lm, \rho)=\rho^{-1}\big(\nabla\menv\big(\Phi(u)+\rho^{-1}{\lm}\big) - \lm\big)
= \Phi(u)-\prox \big(\Phi(u)+ \rho^{-1}\lm\big),
\end{equation} 
 which in turn yields  the relationships
\begin{eqnarray*} 
\L(u,\lambda,\rho)&\ge&\L(u,\olm,\rho)-\langle\nabla_\lambda\L(u,\lambda,\rho),\olm-\lambda\rangle\nonumber\\
&=&\L(u,\olm,\rho)-\big\langle \Phi(u)-\prox\big(\Phi(u)+ \rho^{-1}{\lm}\big),\olm-\lambda\big\rangle\nonumber\\
&\ge& \ph(\ox)+g(\Phi(\ox))+\ell\Vert u-\ox\Vert^2-\big\langle \Phi(u)-\prox\big(\Phi(u)+ \rho^{-1}{\lm} \big),\olm-\lambda\big\rangle
\end{eqnarray*}
with the last inequality resulting from  \eqref{eq16}. We conclude from  $u\in S_\rho(\lambda)$ that 
\begin{equation*}
\L(u,\lambda,\rho)\le\L(\ox,\lambda,\rho)=\ph(\ox)+\menv\big(\Phi(\ox)+\rho^{-1}{\lm}\big) - \sm \rho^{-1}{\|\lm\|^2}\leq \ph(\ox)+g \big(\Phi(\ox) \big).
\end{equation*}
Combining these brings us to 
\begin{equation}\label{eq20}
\Vert u-\ox\Vert^2\le\frac{1}{\ell}\big\langle \Phi(u)-\prox\big(\Phi(u)+\rho^{-1}\lm\big),\olm-\lambda\big\rangle.
\end{equation}
By the first equality in \eqref{prm}, the inclusion  $\olm \in \partial g\big(\Phi(\ox)\big)$ amounts to $\Phi(\ox) = \prox\big(\Phi(\ox)+ \rho^{-1}\olm\big)$. This leads us to 
\begin{eqnarray}\label{clq7}
&&\big\Vert\Phi(u)-\prox\big(\Phi(u)+\rho^{-1}\lm\big)\big\Vert \nonumber\\
&=&\big\Vert\Phi(u)-\Phi(\ox)+\prox\big(\Phi(\ox)+\rho^{-1}\olm\big)-\prox\big(\Phi(u)+\rho^{-1}\lm\big)\big\Vert\nonumber\\
&\le&2\Vert\Phi(u)-\Phi(\ox)\Vert+\rho^{-1}{\Vert\olm-\lambda\Vert}\nonumber\\
&\le&2\kappa_\Phi\Vert u-\ox\Vert+\rho^{-1}{\Vert\olm-\lambda\Vert},
\end{eqnarray}
where the first inequality comes from  the fact that proximal mapping of a convex function is always nonexpansive (cf.  \cite[Proposition~12.19]{rw}), 
and where the last inequality results from \eqref{eq49}. This, combined with  \eqref{eq20},  brings us   to 
\begin{equation*}
\Vert u-\ox\Vert^2\le\frac{1}{\ell}\Big(2\kappa_\Phi\Vert u-\ox\Vert+\rho^{-1}{\Vert\lambda-\olm\Vert}\Big)\Vert\lambda-\olm\Vert.
\end{equation*}
Since the latter inequality  can be expressed  equivalently as 
\begin{equation*}
\ell\Vert u-\ox\Vert^2-2\kappa_\Phi\Vert \lambda-\olm\Vert\cdot\Vert u-\ox\Vert-\rho^{-1}{\Vert \lambda-\olm\Vert^2 }\le 0,
\end{equation*}
we arrive at  the estimate
\begin{equation*}
\Vert u-\ox\Vert\le\left(\dfrac{\kappa_\Phi}{\ell}+\sqrt{\frac{\kappa_\Phi^2}{\ell^2}+\frac{1}{\ell\rho}}\right)\Vert\lambda-\olm\Vert\le\tau\Vert\lambda-\olm\Vert \le \tau \hat\gamma/2\tau < \hat\gamma.
\end{equation*}
This clearly justifies   \eqref{pt9}   and  the inclusion $S_\rho(\lambda)\subset  \inte  \B_{\hat\gamma}(\ox)$ for all  $\lambda\in \B_{\hat\gamma/2\tau} (\olm)$ and $\rho\geq\bar\rho$,  and hence completes the proof.
\end{proof}

\begin{Remark}{\rm Assume that  the SOSC \eqref{sosc} holds at $(\ox,\olm)$. It is not hard to see that a similar argument as those for \eqref{eq20}
shows that for any $\lm\in \R^m$, any $u\in S_\rho(\lm)$,  any $\mu \in \Lm(\ox)\cap \B_\ve(\olm)$, and any $\rho\ge \bar\rho$ we have 
\begin{equation*} 
\Vert u-\ox\Vert^2\le\frac{1}{\ell}\big\langle \Phi(u)-\prox\big(\Phi(u)+\rho^{-1}\lm\big),\mu-\lambda\big\rangle,
\end{equation*}
where constants $\bar\rho$, $\ve$, and $\ell$ come from Theorem~\ref{ugrowth}.
Combining this and the second equality in \eqref{ueq19} brings us to 
\begin{equation}\label{ueq20}
\Vert u-\ox\Vert^2\le\frac{1}{\ell\rho}\big\langle \nabla e_{1/\rho}\big(\Phi(u)+\rho^{-1}\lm\big)-\lm,\mu-\lambda\big\rangle,
\end{equation}
which will be utilized in the proof of Theorem~\ref{est} later in this section.
}
\end{Remark}

\begin{Proposition}[estimate for residual functions] \label{erct}  Assume that $(\ox,\olm)$ is a solution to the KKT system \eqref{vs} with $\Th$ taken from \eqref{Th}. Then 
there exist positive constants $\gamma_2$ and $\kappa_2$ such that
\begin{equation}\label{eb1}
R(x, \lambda) \leq \kappa_2\big(\|x-\ox\|+\dist(\lambda, \Lambda(\ox))\big)\quad\textrm{for all }\;\; (x, \lambda)\in \B_{\gamma_2}(\ox, \olm).
\end{equation} 
\end{Proposition}

\begin{Theorem}[error bound for consecutive iterates of ALM]\label{est} 
Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and  let the SOSC \eqref{sosc} hold at $(\ox,\olm)$. Then there exist positive constants   $\gamma_3$, and $\kappa_3$ such that for any $\rho\geq \bar\rho$ with 
$\bar\rho$ taken from Theorem~{\rm\ref{ugrowth}}, any $(x,\lambda)\in\B_{\gamma_3}(\ox,\olm)$ with $x\in \Th$ and  $R(x,\lambda)>0$, and any   optimal solution $u$ to the regularized problem 
\begin{equation}\label{regp}
\mini \L(w, \lm, \rho)\quad \mbox{subject to}\quad w\in \Th\cap \B_{\hat\gg}(\ox)
\end{equation} 
with $\hat\gg$ taken from Proposition~{\rm\ref{solv}},   the error bound estimate
\begin{equation}\label{est0}
\Vert u-x\Vert+\big\Vert\nabla\menv\big(\Phi(u)+ \rho^{-1}{\lm}\big)-\lm\big\Vert\le\kappa_3\,R(x,\lambda)
\end{equation}
holds, where the residual function  $R$ is  taken from \eqref{res}.
\end{Theorem}

\begin{proof} It follows from the SOSC \eqref{sosc} and    Theorem~\ref{ugrowth} that there are positive  constants $\bar\rho$, $\gamma$, $\varepsilon$, and $\ell$ for which 
the uniform quadratic  growth condition \eqref{eq14} holds  for all $\rho\ge\bar\rho$ and all $\lambda\in\Lambda(\ox)\cap\B_\varepsilon(\olm)$. 
According to Proposition~\ref{solv}, the solution mapping to \eqref{regp}, denoted by $S_\rho(\lm)$ therein, satisfies the uniform isolated calmness \eqref{pt9} and the condition $S_\rho(\lm)\subset  \inte  \B_{\hat\gamma}(\ox)$ for all $\lm\in \B_{\hat\gamma/2\tau}(\olm)$ and all $\rho\ge \bar\rho$, where both positive constants $\tau$ and $\hat\gg$ are taken from this proposition. This, in particular, tells us that for every $\lm\in \B_{\hat\gamma/2\tau}(\olm)$ and every $\rho\ge \bar\rho$
any optimal solution $u$ to \eqref{regp} satisfies the first-order optimality condition 
\begin{equation}\label{optc}
0\in \nabla_x\L(u, \lm, \rho)+ N_\Th(u).
\end{equation}
After this presentation, assume by contradiction that the error bound estimate \eqref{est0} fails. The latter implies that  there exists a sequence $\{(\xk, \lk, \rok)\b\subset \Th \times \R^m\times [\bar\rho, \infty)$ 
with $\xk\to\ox, \lk\to\olm$ as $k\to\infty$ such that
\begin{equation}\label{est1}
\Vert u^k-\xk\Vert+\| d^k-\lk\|>kR_k\quad \mbox{with}\;\;d^k:=\nabla\menvk\big(\Phi(u^k)+\rho_k^{-1}\lk\big),
\end{equation} 
where $u^k$ is an optimal solution to \eqref{regp} for $(\lambda, \rho):=(\lk, \rok)$, and where $R_k:=R(\xk, \lk)$ for each $k \in \mathbb{N}$. Denote by $\beta_k$ the left-hand side of \eqref{est1}, and thus get $R_k=o(\beta_k)$.
 By the definition of $R_k$, the latter yields
\begin{equation}\label{est2}
-\nabla_xL(\xk, \lk)+o(\xik)\in N_\Th(\xk)\quad\textrm{and}\quad \Phi(\xk)+o(\xik)= {\rm{prox}}_g\big(\Phi (\xk)+\lk\big).
\end{equation}
Passing to a subsequence if necessary, we can find $(\xi,\eta)\in \R^n\times \R^m$ such that 
\begin{equation}\label{est4}
\dfrac{u^k-\xk}{\xik}\to \xi\quad \mbox{and}\quad  \dfrac{ d^k-\lk}{\xik} \to  \eta \quad \mbox{with}\;\; (\xi,\eta)\neq 0.
\end{equation}
We know from Theorem~\ref{sooc} that the error bound \eqref{subr3} holds for all $(x,\lm)$ sufficiently close to  $(\ox, \olm)$. 
Set $\mu^k:=P_{\Lambda(\ox)}(\lk)$ and remember  that $(\xk, \lk)\to(\ox, \olm)$.  By  \eqref{subr3}, we can assume without loss of generality that $\xk-\ox=O(R_k)$ and $\lk-\mu^k=O(R_k)$ for all $k\in \N$, which in turn results in
\begin{equation}\label{est3}
\xk-\ox=o(\xik)\quad\textrm{and}\quad\lk-\mu^k=o(\xik)\quad\textrm{as } k\to\infty.
\end{equation}
The latter along with $\lk\to \olm$ tells us that $\mu^k\to \olm$. So, we get   $\mu^k\in\Lambda(\ox)\cap\B_\varepsilon(\olm)$ for all $k $ sufficiently large. 
This, combined with  $\rho_k\ge\bar\rho$ and \eqref{ueq20}, implies that 
\begin{eqnarray}\label{est5}
\Vert u^k-\ox\Vert^2&\le&\dfrac{1}{\rok\ell} \langle d^k-\lk,\mu^k-\lk \rangle\le\dfrac{1}{\rok\ell}\| d^k-\lk\|\cdot\Vert\mu^k-\lk\Vert,
\end{eqnarray}
which together with \eqref{est4} and  \eqref{est3} results in 
\begin{equation*}
\dfrac{\Vert u^k-\ox\Vert^2}{\xik^2}\le\dfrac{1}{\rok\ell}\dfrac{\| d^k-\lk\|}{\xik}\cdot\dfrac{\Vert\mu^k-\lk\Vert}{\xik}\to 0\quad\textrm{ as }\;k\to\infty.
\end{equation*}
Thus, we get $u^k-\ox=o(\beta_k)$. Combining this with \eqref{est3} clearly shows that 
\begin{equation*}
\xi=\lim_{k\to\infty}\dfrac{u^k-\xk}{\xik}=\lim_{k\to\infty}\dfrac{u^k-\ox}{\xik}-\lim_{k\to\infty}\dfrac{\xk-\ox}{\xik}=0-0=0.
\end{equation*}
If either the sequence $\{\rok\b$ or  $\{{\rok}/{\xik}\b$ is bounded, it follows from $u^k-\ox=o(\beta_k)$ that  $\dfrac{\rok}{\xik}\Vert u^k-\ox\Vert\to0$ as $k\to\infty$. 
This, \eqref{ueq19}, and a similar argument as those for \eqref{clq7} bring us to 
\begin{eqnarray*}
 \dfrac{ \|d^k-\lk\|}{\xik}
&=&\frac{\rok}{\xik} \big\Vert \Phi(u^k)-\proxk\big(\Phi(u^k)+\rho_k^{-1}\lk\big)\big\Vert\\
&\leq& 2\kappa_\Phi\frac{\rok}{\xik}\|u^k-\ox\|+\dfrac{\Vert \mu^k-\lk\Vert }{\xik}\to0\quad\textrm{as } k\to\infty,  
\end{eqnarray*} 
which by \eqref{est4} yields $\eta =0$. This is  a contradiction with \eqref{est4} since we showed that $(\xi,\eta)=0$.

Assume now that both sequences $\{\rok\b$ and  $\{{\rok}/{\xik}\b$  are unbounded.  We can assume by passing  to a subsequence if necessary that 
\begin{equation}\label{unb}
\rok\to \infty\quad \mbox{and}\quad \frac{\rok}{\beta_k}\to \infty\;\;\mbox{as}\;\; k\to \infty.
\end{equation}
Since $u^k$ is an optimal solution to \eqref{regp} associated with $(\lk,\rok)$, we deduce from \eqref{optc} that 
\begin{equation*}
0\in \nabla_x\L(u^k, \lk, \rok)+ N_\Th(u^k).
\end{equation*} 
By \eqref{Th}, we get  $N_{\Th}(u^k)=N_\Th(\xk) = \rge B^*$. These along with  \eqref{est2} tell us that 
\begin{equation*}
\nabla_x\L(u^k, \lk, \rok)-\nabla_xL(\xk, \lk)+o(\xik)\in N_\Th(\xk)-N_\Th(u^k)= \rge B^*.
\end{equation*}
Using the definitions of the augmented Lagrangian $\L$ and  $L$, we get 
\begin{eqnarray*}
\rge B^*&\ni& \nabla_x\L(u^k, \lk, \rok)-\nabla_xL(\xk, \lk)+o(\xik)\\
&=&\nabla \varphi(u^k)-\nabla \varphi(\xk)+\nabla\Phi(u^k)^* \nabla\menvk\big(\Phi(u^k)+\rho_k^{-1}\lk\big)-\nabla\Phi(\xk)^*\lk+o(\xik)\\
&=&\big(\nabla\Phi(u^k)-\nabla\Phi(\xk)\big) ^*\lk+\nabla\Phi(u^k)^*\big (d^k-\lk\big )+o(\xik)\\
&=&\nabla\Phi(u^k)^* \big(d^k-\lk\big)+o(\xik),
\end{eqnarray*}
where the second and last equalities result from  the Lipschitz continuity of  $\nabla \varphi$ and $\nabla \Phi$ around $\ox$ and from  the fact that $u^k-\xk=o(\xik)$. 
Dividing both sides  by $\xik$ and then letting  $k\to\infty$ confirm via \eqref{est4} that 
\begin{equation*}
\nabla\Phi(\ox)^*\eta \in\rge B^*.
\end{equation*} 
We are going to show that $\eta=0$, which contradicts \eqref{est4} and thus completes the proof. To furnish this, set $E:=\big\{z \in \R^n\, |\, \nabla \Phi(\ox)^*z\in \rge B^*\big\}$
and observe from \cite[Corollary~11.25(d)]{rw} that $E^\perp=\big\{\nabla\Phi(\ox)y|\;y\in \ker B\big\}$. So, we conclude  from  $\ox,u^k\in \Th$ and  \eqref{Th} that $\nabla\Phi(\ox)(u^k-\ox)\in E^\perp$.
Moreover, we obtain  from \eqref{est4}-\eqref{est5} that 
\begin{equation}\label{est6}
\dfrac{\rok}{\xik}\Vert u^k-\ox\Vert^2\leq\dfrac{1}{\ell} \dfrac{\| d^k-\lk\|}{\xik} \cdot\Vert \mu^k-\lk\Vert  \to 0 \quad\textrm{ as }k\to\infty.
\end{equation} 
Since $P_E$ is a linear mapping due to $E$ being a subspace, we arrive at 
\begin{eqnarray}\label{est7}
P_E\Big(\dfrac{\rok}{\xik}\big (\Phi(u^k)-\Phi(\ox)\big )\Big)&=&P_E\Big (\dfrac{\rok}{\xik}\nabla\Phi(\ox) (u^k-\ox )+O\big (\dfrac{\rok}{\xik}\Vert u^k-\ox\Vert^2 \big)\Big  )\nonumber\\
&=&P_E \Big(O\big(\dfrac{\rok}{\xik}\Vert u^k-\ox\Vert^2 \big )\Big)\to 0 \quad \textrm{as } k\to\infty,
\end{eqnarray} 
where the last equality results from $\nabla\Phi(\ox)(u^k-\ox)\in E^\perp$.
Fix $k\in \N$ and set  
$
z^k:= \Phi(u^k)+ \rho_k^{-1}\big(\lk -d^k\big).
$
It follows from $d^k=\nabla\menvk\big(\Phi(u^k)+ \rho_k^{-1}{\lk}\big)$ and the second equation in \eqref{prm} that 
\begin{equation}\label{clq8}
d^k \in \partial g(z^k).
\end{equation} 
Using  \eqref{est4} and \eqref{unb} allows us to arrive at 
\begin{equation*}
z^k =\Phi(u^k) - \frac{d^k-\lk}{\xik}\cdot\frac{\xik}{\rok} \to \Phi(\ox)=:\bar z\quad\textrm{as }\; k\to\infty.
\end{equation*} 
By \eqref{clq8}, we get $z^k\in \dom g=\cup_{i=1}^s C_i$ for all $k$, where the polyhedral convex sets $C_i$ are taken from \eqref{PWLQ}. 
By passing to a subsequence if necessary, we can assume without loss of generality that  for some $\oi\in I(\oz)$, we have $z^k \in C_\oi$ for all $k$, where the index set  $  I(\bar z)$  is defined by \eqref{act}.
Since $C_\oi$ is  polyhedral, we find   $l_\oi\in \N$, $c_{\oi, j}\in \R^m$, and $\al_{\oi, j}\in \R$,  $j=1,\ldots,l_\oi$,  such that 
\begin{equation*}
C_\oi= \big\{z\in \R^m\, |\, \langle c_{\oi, j}, z\rangle \leq \al_{\oi, j}, \quad j= 1, \ldots, l_\oi\big\}.
\end{equation*} 
Denote by $J(\bar z)$ and $J(z^k)$ the sets of the indexes of active inequalities in $C_\oi$ at $\bar z$ and $z^k$, respectively. Since $z^k\to \oz$, we obtain  $J(z^k)\subset J(\bar z)$ for all $k$ sufficiently large. 
Passing to a subsequence, if necessary, we can assume that there exists a subset $\bar J\subset J(\bar z)$ such that $J(z^k)=\bar J$ for all $k$. Thus, we have 
\begin{equation*}
z^k -\bar z \in \big\{v\in \R^m\, \big|\, \langle c_{\oi, j}, v\rangle= 0\;\textrm{ for } \;j \in \bar J, \; \langle c_{\oi, j}, v\rangle\leq 0\; \textrm{ for }\; j\in J(\bar z)\setminus \bar J \big\}=: \Omega.
\end{equation*} 
It follows from  the definitions of $z^k$ and $\bar z$ that 
\begin{equation*}
\Phi(u^k)-\Phi(\ox)-\frac{ d^k-\lk}{\rok}=z^k-\oz \in \Omega. 
\end{equation*}
Multiplying by $ {\rok}/{\xik}$ and using the linearity of  $P_E$  allow us to get 
\begin{equation*}
P_E\Big(\dfrac{\rok}{\xik}\big (\Phi(u^k)-\Phi(\ox)\big )\Big)- P_E \big(\frac{ d^k-\lk}{\xik}\big) \in P_E(\Omega),
\end{equation*} 
which, together with \eqref{est4}, \eqref{est7}, and the closedness of $P_E(\Omega)$, yields $-P_E(\eta) \in P_E(\Omega)$. Since $\eta\in E$, the latter confirms that 
\begin{equation}\label{est8}
-\eta=-P_E(\eta) = P_E(\zeta)\quad\textrm{for some }\;\; \zeta\in \Omega.
\end{equation}
Remembering $\mu^k\in \Lm(\ox)$, we obtain $\mu^k \in \partial g(\bar z)$. By the representation of $\partial g(\bar z)$ from \eqref{sub} and the fact that  $\oi\in I(\bar z)$, we conclude that 
\begin{equation*}\label{clq9}
\mu^k - A_\oi\bar z -a_\oi \in N_{C_\oi}(\bar z) = \cone\big\{c_{\oi, j}\, | \;j\in J(\bar z)\big\}.
\end{equation*} 
Since we also have $\oi\in I(z^k)$, it follows again from \eqref{clq8} and  \eqref{sub} that 
\begin{equation*}\label{clq10}
d^k -A_\oi z^k-a_\oi \in N_{C_\oi}(z^k) = \cone\big\{c_{\oi, j}\,|\; j\in \bar J\big\}.
\end{equation*} 
Combining these results in 
\begin{eqnarray*}
 \mu^k-d^k + A_\oi(z^k-\bar z)&\in&   \cone\big\{c_{\oi, j}\, | \;j\in J(\bar z)\big\}-\cone\big\{c_{\oi, j}\,|\; j\in \bar J\big\}\\
&=&\span\big\{c_{\oi, j}\,|\;  j\in \bar J\big\}+\cone\big\{c_{\oi, j}\,|\; j\in J(\bar z)\setminus\bar J\big\} =  \Omega^*.
\end{eqnarray*} 
Since $\lk -\mu^k=o(\xik)$ and $u^k-\ox=o(\beta_k)$, we deduce from \eqref{est4} and \eqref{unb} that 
\begin{eqnarray*}
\frac{ \mu^k-d^k}{\beta_k}+A_\oi\big(\frac{z^k-\oz}{\beta_k}\big)&=& \frac{ \mu^k-\lk}{\beta_k}+\frac{ \lk-d^k}{\beta_k} +A_\oi\big(\frac{\Phi(u^k)-\Phi(\ox)}{\beta_k}\big)\\
&&-\frac{1}{\rok}A_\oi\big(\frac{d^k-\lk}{\beta_k}\big)\to -\eta \;\;\;\;\mbox{as}\;\;k\to \infty,
\end{eqnarray*}
which in turn demonstrates that 
$-\eta \in \Omega^*$. This, combined with \eqref{est8} and $\eta\in E$, shows that 
\begin{equation*}
\|\eta\|^2= \langle \eta, \eta \rangle = \langle \eta, P_E(\eta) \rangle= -\langle \eta, P_E(\zeta) \rangle= -\big\langle \eta, P_E(\zeta)+P_{E^{\perp}}(\zeta) \big\rangle = -    \langle \eta, \zeta\rangle \le 0,
\end{equation*} 
implying that  $\eta =0$. This clearly contradicts \eqref{est4} and thus completes the proof.
\end{proof}

\begin{proof}
 Define $R_k:=R(\xk,\lk)$   and observe that if $R_k=0$ for some $k$, then the pair $(\xk,\lk)$ satisfies the KKT system \eqref{vs}, and thus Algorithm \ref{Alg1} should stop. From now on assume that $R_k>0$ for all $k\in\N$. 
  Pick the positive constants $\kappa_1$ and $\gg_1$ from Theorem~\ref{sooc}, the positive constants $\gamma_2$ and $\kappa_2$ from Proposition~\ref{erct}, the positive constants 
  $\gamma_3$ and $\kappa_3$ from Theorem~\ref{est}, and the positive constants $\hat\gg$ and $ \tau$ from Proposition~\ref{solv}. By \eqref{error}, we can find $\gamma_4>0$ such that
\begin{equation}\label{ek}
\sigma(x,\lm)\le\dfrac{1}{4\kappa_1\kappa_2}R(x,\lm)\quad\textrm{ whenever }\;(x,\lm)\in\B_{\gg_4}(\ox,\olm).
\end{equation}
Define further the  positive  constants  $\bar\tau:=\kappa_3$ and 
\begin{equation}\label{const}
\bar\gamma:=\dfrac{\gamma'}{1+2\sqrt{2}\bar\tau\kappa_2} \quad\mbox{with}\quad
\gamma':=\min\Big\{\frac{\hat\gg}{2\tau},\gamma_3,\gamma_4,\dfrac{\gamma_1}{1+\sqrt{2}\bar\tau\kappa_2},\dfrac{\gamma_2}{1+\sqrt{2}
\bar\tau\kappa_2}\Big\}.
\end{equation}
Moreover, pick $q\in (0,1) $ and set 
\begin{equation}\label{rhof}
\bar\varrho:=\max\big\{\bar\rho, 4\kappa_1\kappa_2\bar\tau, \frac{2\sqrt{2} \kappa_1\kappa_2^2\bar\tau^2}{q}\big\},
\end{equation}
where  $\bar\rho$ is taken from Theorem~\ref{ugrowth}. 
Arguing by induction, we aim at showing that for any starting point $(x^0,\lambda^0)\in\big(\Th\times\R^m\big)\cap\B_{\bar\gamma}(\ox,\olm)$ there exists a sequence $\{(\xk,\lk)\c\subset \Th \times\R^m$, generated by Algorithm~\ref{Alg1}
with $\rok \ge \bar\varrho$ and   $\ek=\sigma(\xk,\lk)$ for all $k$,
 such that for all $k=0,1,\ldots$ the relationships
\begin{equation}\label{c1}
(\xk,\lk)\in\B_{\gamma'}(\ox,\olm),
\end{equation}
\begin{equation}\label{c2}
\dist\big(-\nabla_x L(\xkk,\lkk), N_\Th(\xkk)\big)\le\ek\quad\textrm{ and }\quad\Vert\xkk-\xk\Vert+\Vert\lkk-\lk\Vert\le\bar\tau R_k
\end{equation}
hold. To achieve this goal, set $k=0$, pick $(x^0,\lambda^0)\in\big(\Th\times\R^m\big)\cap\B_{\bar\gamma}(\ox,\olm)$, and observe from  $\bar\gamma\le\gamma'$ that \eqref{c1} holds in this case. We also have $\lambda^0\in\B_{\hat\gg/2\tau}(\olm)$ and $\rho_0\ge \bar\varrho$ and then find by Proposition~\ref{solv} a primal iterate $x^1\in \inte \B_{\hat\gamma}(\ox)$ satisfying $-\nabla_x\L(x^1,\lambda^0,\rho_0)\in N_\Th(x^1)$. Define further 
the multiplier $\lm^1:=\nabla e_{1^{}/\rho_0}g\big(\Phi(x^1)+ \rho_0^{-1}\lambda^0\big)$ and observe that
\begin{equation*}
-\nabla_x L(x^1,\lm^1)=-\nabla_x\L(x^1,\lambda^0,\rho_0)\in N_\Th(x^1).
\end{equation*}
Moreover, employing  Theorem~\ref{est} confirms that 
\begin{equation*}
\Vert x^1-x^0\Vert+\Vert\lm^1-\lambda^0\Vert\le\bar\tau R_0.
\end{equation*}
Thus $(x^1,\lambda^1)$ is well defined and satisfies the claimed condition \eqref{c2} for $k=0$. Assume by induction that the iterates $(\xk,\lk)$, $k=0,1,\ldots,s+1$, are well defined  and that   both conditions \eqref{c1} and \eqref{c2} hold for $k=0,1,\ldots,s$. We verify now the existence of $(x^{s+2},\lambda^{s+2})$ satisfying \eqref{c1} and \eqref{c2} for $k=s+1$. To this end, we first show that $(x^{s+1},\lambda^{s+1})\in\B_{\gamma'}(\ox,\olm)$. 
To proceed, fix an integer   $k$ with $0\le k\le s$.
Since $(\xk,\lk)\in\B_{\gamma'}(\ox,\olm)$, it follows from \eqref{eb1} and \eqref{c1} that
\begin{eqnarray}\label{c3}
R_k&\le&\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\\
&\le&\kappa_2\big(\Vert\xk-\ox\Vert+\Vert\lk-\olm\Vert\big)\le\sqrt{2}\kappa_2\Vert(\xk,\lk)-(\ox,\olm)\Vert\le\sqrt{2}\kappa_2\gamma'.\nonumber
\end{eqnarray}
Combining this with \eqref{c1} and the second relation in \eqref{c2}, we conclude that
\begin{eqnarray}\label{c4}
\Vert(\xkk,\lkk)-(\ox,\olm)\Vert&\le&\Vert\xkk-\xk\Vert+\Vert\lkk-\lk\Vert+\Vert(\xk,\lk)-(\ox,\olm)\Vert\nonumber\\
&\le&\bar\tau R_k+\gamma'\le(\sqrt{2}\bar\tau\kappa_2+1)\gamma'\le\gamma_1,
\end{eqnarray}
which implies that $(\xkk,\lkk)\in\B_{\gamma_1}(\ox,\olm)$. Using \eqref{subr3}, we obtain
\begin{eqnarray}\label{c5}
&&\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\nonumber\\
&\le&\kappa_1 R_{k+1} =\kappa_1\Big(\dist\big(-\nabla_x L(\xkk,\lkk), N_\Th(\xkk)\big) +\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert\Big)\nonumber\\
&\le&\kappa_1\ek+\kappa_1\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert.
\end{eqnarray}
To proceed further,  define
\begin{equation}\label{skk}
\skk:=\proxk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big ).
\end{equation}
It follows from  \eqref{lkk}  and \eqref{ueq19} that
\begin{equation}\label{eq3}
\Phi(\xkk)-\skk= \rho_k^{-1}(\lkk-\lk).
\end{equation}
Since $\lkk=\nabla\menvk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big)$, we deduce from the second equality in \eqref{prm} that 
\begin{equation*}\label{clq17}
\lkk   \in \sub g\big(\Phi(\xkk)+ \rho_k^{-1}(\lk-\lkk)\big)=\partial g(\skk).
\end{equation*} 
Appealing now to the first equality in \eqref{prm} yields $\skk={\rm{prox}}_g(\skk+\lkk)$. Since the mapping $y\mapsto y-{\rm{prox}}_g(y+\lkk)$ is nonexpansive (cf. \cite[Proposition~12.27]{bc}), we arrive at the relationships
\begin{eqnarray}\label{eq2}
&&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert\nonumber\\
&=&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert-\big\Vert\skk-{\rm{prox}}_g(\skk+\lkk)\big\Vert\nonumber\\
&\le&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)-\big(\skk-{\rm{prox}}_g(\skk+\lkk)\big)\big\Vert\nonumber\\
&\le&\Vert\Phi(\xkk)-\skk\Vert.
\end{eqnarray}
Combining \eqref{c5}, \eqref{eq3}, and \eqref{eq2} brings us to
\begin{equation*}
\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\le\kappa_1\ek+\rho_k^{-1}{\kappa_1}\Vert\lkk-\lk\Vert.
\end{equation*}
This,  together with \eqref{ek}, \eqref{rhof}, the second inequality in \eqref{c2}, and \eqref{c3} results in 
\begin{eqnarray}\label{c10}
\Vert \xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)&\le&\kappa_1\ek+\dfrac{\bar\tau\kappa_1}{\rok}R_k\le\dfrac{1}{4\kappa_2}R_k +\dfrac{1}{4\kappa_2}R_k\\
&\le&\dfrac{1}{2}\Big(\Vert\xk-\ox\Vert+\dist\big(\lk,\Lambda(\ox)\big)\Big)\nonumber,
\end{eqnarray}
which in turn implies the primal-dual estimates
\begin{equation}\label{c6}
\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\le\dfrac{1}{2^{k+1}}\Big(\Vert x^0-\ox\Vert+\dist\big(\lambda^0,\Lambda(\ox)\big)\Big).
\end{equation}
This estimate, \eqref{c3},  and the second inequality in \eqref{c2} tell us that 
\begin{eqnarray}\label{c7}
\Vert(x^{s+1},\lambda^{s+1})-(x^0,\lambda^0)\Vert&\le&\sum\limits_{k=0}^s\Vert(\xkk,\lkk)-(\xk,\lk)\Vert \le\bar\tau\sum\limits_{k=0}^s R_k\nonumber\\
&\le&\bar\tau\kappa_2\sum\limits_{k=0}^s\Vert\xk-\ox\Vert+\dist\big(\lk,\Lambda(\ox)\big)\nonumber\\
&\le&\bar\tau\kappa_2\sum\limits_{k=0}^s\dfrac{1}{2^k}\Big(\Vert x^0-\ox\Vert+\dist\big(\lambda^0,\Lambda(\ox)\big)\Big)\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\dist(\lambda^0,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\Vert\lambda^0-\olm\Vert\big).\nonumber
\end{eqnarray}
Thus, we arrive at the estimates
\begin{eqnarray*}
\Vert(x^{s+1},\lambda^{s+1})-(\ox,\olm)\Vert&\le&\Vert(x^{s+1},\lambda^{s+1})-(x^0,\lambda^0)\Vert+\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\Vert\lambda^0-\olm\Vert\big)+\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\\
&\le&(2\sqrt{2}\bar\tau\kappa_2+1)\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\le(2\sqrt{2}\bar\tau\kappa_2+1)\bar\gamma=\gamma',
\end{eqnarray*}
where the last inequality follows from $(x^0,\lambda^0)\in\B_{\bar\gamma}(\ox,\olm)$, while the last equality comes from the definition of $\bar\gamma$ in \eqref{const}. 
This verifies that $(x^{s+1},\lambda^{s+1})\in\B_{\gamma'}(\ox,\olm)$. By  \eqref{const}, we get  $\lambda^{s+1}\in\B_{\hat\gg/2\tau}(\olm)$, and hence Proposition~\ref{solv} ensures the existence of of an optimal solution $x^{s+2}$ 
to \eqref{regp} associated with $(\lm^{s+1},\rho_{s+1})$ such that $x^{s+2}\in \inte\B_{\hat\gamma}(\ox)$. The latter yields 
\begin{equation*}
-\nabla_x\L(x^{s+2},\lambda^{s+1},\rho_{s+1})\in N_\Th(x^{s+2}).
\end{equation*} 
Set now $\lm^{s+2}:=\nabla e_{1^{}/\rho_{s+1}}\big(\Phi(x^{s+2})+\rho_{s+1}^{-1}\lambda^{s+1}\big)$ and observe that
\begin{equation*}
 -\nabla_x L(x^{s+2},\lm^{s+2}) =  -\nabla_x\L(x^{s+2},\lambda^{s+1},\rho_{s+1}) \in N_\Th(x^{s+2}),
\end{equation*}
which by Proposition~\ref{est} brings us to the estimate
\begin{equation*}
\Vert x^{s+2}-x^{s+1}\Vert+\Vert\lm^{s+2}-\lambda^{s+1}\Vert\le\bar\tau R_{s+1}.
\end{equation*}
This tells us that the iterate $(x^{s+2},\lambda^{s+2})$ satisfies   \eqref{c2} for $k=s+1$, which completes  the proof of  induction. Thus there exists a sequence  $\{(\xk,\lk)\c\subset\Th\times\R^m$, generated by Algorithm~\ref{Alg1} 
with $\rok \ge \bar\varrho$ and   $\ek=o\big(R(\xk,\lk)\big)$ for all $k$, for which  \eqref{c1} and \eqref{c2} fulfill.


Next, we are going to justify  the convergence of this primal-dual   sequence. Using the same arguments as in the proofs of \eqref{c6} and \eqref{c7} leads us to
\begin{equation}\label{c8}
\Vert(x^{k+l},\lambda^{k+l})-(\xk,\lk)\Vert\le 2\bar\tau\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\quad\mbox{for all}\;\;k,l\in\N.
\end{equation}
It follows from \eqref{c6} that the right-hand side of \eqref{c8} goes to zero as $k\to\infty$, which tells us that the sequence $\{(\xk,\lk)\c$ is Cauchy. By \eqref{c6},   this sequence converges  to $(\ox,\hat\lambda)$ for some $\hat\lambda\in\Lambda(\ox)$.
Now, we show  that  the rate of this convergence is linear. Indeed, letting $l\to\infty$ in \eqref{c8} tells us that for all $k\in\N$ we have
\begin{equation*}\label{c9}
\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert\le 2\bar\tau\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big),
\end{equation*}
which together with the first inequality in \eqref{c10} verifies that
\begin{eqnarray*}
\Vert(\xkk,\lkk)-(\ox,\hat\lambda)\Vert&\le&2\bar\tau\kappa_2\big(\Vert\xkk-\ox\Vert+\dist(\lkk,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)R_k\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\big(\Vert\xk-\ox\Vert+\Vert\lk-\hat\lambda\Vert\big)\nonumber\\
&\le& 2\sqrt{2}\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert.
\end{eqnarray*}
Combining this with $\rok\ge \bar\varrho$  with $ \bar\varrho$ taken from \eqref{rhof} and using the choice of the tolerance $\ek=o(R_k)$ result in 
\begin{equation*}
\limsup_{k\to\infty}\dfrac{\Vert(\xkk,\lkk)-(\ox,\hat\lambda)\Vert}{\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert}\le\limsup_{k\to\infty}2\sqrt{2}\bar\tau
\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\le q.
\end{equation*}
It follows from  $q\in (0,1)$ that the rate of   convergence of $\{(\xk,\lk)\c$ is linear. Furthermore, it is clear from the above inequality that if $\rok\to \infty$, we 
arrive at the superlinear convergence of the latter primal-dual sequence, which completes the proof.
\end{proof}

