\begin{Theorem}[primal-dual linear convergence of ALM]\label{locpd} 
 Let $(\ox,\olm)$ be a solution to the KKT system \eqref{vs} and  let the SOSC \eqref{sosc} hold at $(\ox,\olm)$.
 Then there exist positive constants $\bar\gg$, $\bar\tau$, and $\bar\varrho$ such that for any starting point $(x^0,\lm^0)\in \B_{\bar\gg}(\ox,\olm)\cap\big(\Th\times \R^m\big)$
 there is a primal-dual sequence   $\{(\xk,\lk)\c$,  generated by Algorithm~{\rm\ref{Alg1}} with $\rok \ge \bar\varrho$ and   $\ek=\sigma(\xk,\lk)$ for all $k$, where $\sigma$ is defined by \eqref{error}, satisfying the  estimate
 \begin{equation}\label{cone}
 \|x^{k+1}-x^k\|+\|\lm^{k+1}-\lk\|\le \bar\tau R(x^k,\lk),
 \end{equation}
 where $R$ is the residual function defined by  \eqref{res}.
  Moreover, every such a sequence is convergent to $(\ox,\hat\lambda)$ for some $\hat\lambda\in\Lm(\ox)$, and its rate of convergence is linear.
  Furthermore, if $\rok\to \infty$,  the rate of convergence  of $\{(\xk,\lk)\c$ is superlinear. 
\end{Theorem}

\begin{proof}
 Define $R_k:=R(\xk,\lk)$   and observe that if $R_k=0$ for some $k$, then the pair $(\xk,\lk)$ satisfies the KKT system \eqref{vs}, and thus Algorithm \ref{Alg1} should stop. From now on assume that $R_k>0$ for all $k\in\N$. 
  Pick the positive constants $\kappa_1$ and $\gg_1$ from Theorem~\ref{sooc}, the positive constants $\gamma_2$ and $\kappa_2$ from Proposition~\ref{erct}, the positive constants 
  $\gamma_3$ and $\kappa_3$ from Theorem~\ref{est}, and the positive constants $\hat\gg$ and $ \tau$ from Proposition~\ref{solv}. By \eqref{error}, we can find $\gamma_4>0$ such that
\begin{equation}\label{ek}
\sigma(x,\lm)\le\dfrac{1}{4\kappa_1\kappa_2}R(x,\lm)\quad\textrm{ whenever }\;(x,\lm)\in\B_{\gg_4}(\ox,\olm).
\end{equation}
Define further the  positive  constants  $\bar\tau:=\kappa_3$ and 
\begin{equation}\label{const}
\bar\gamma:=\dfrac{\gamma'}{1+2\sqrt{2}\bar\tau\kappa_2} \quad\mbox{with}\quad
\gamma':=\min\Big\{\frac{\hat\gg}{2\tau},\gamma_3,\gamma_4,\dfrac{\gamma_1}{1+\sqrt{2}\bar\tau\kappa_2},\dfrac{\gamma_2}{1+\sqrt{2}
\bar\tau\kappa_2}\Big\}.
\end{equation}
Moreover, pick $q\in (0,1) $ and set 
\begin{equation}\label{rhof}
\bar\varrho:=\max\big\{\bar\rho, 4\kappa_1\kappa_2\bar\tau, \frac{2\sqrt{2} \kappa_1\kappa_2^2\bar\tau^2}{q}\big\},
\end{equation}
where  $\bar\rho$ is taken from Theorem~\ref{ugrowth}. 
Arguing by induction, we aim at showing that for any starting point $(x^0,\lambda^0)\in\big(\Th\times\R^m\big)\cap\B_{\bar\gamma}(\ox,\olm)$ there exists a sequence $\{(\xk,\lk)\c\subset \Th \times\R^m$, generated by Algorithm~\ref{Alg1}
with $\rok \ge \bar\varrho$ and   $\ek=\sigma(\xk,\lk)$ for all $k$,
 such that for all $k=0,1,\ldots$ the relationships
\begin{equation}\label{c1}
(\xk,\lk)\in\B_{\gamma'}(\ox,\olm),
\end{equation}
\begin{equation}\label{c2}
\dist\big(-\nabla_x L(\xkk,\lkk), N_\Th(\xkk)\big)\le\ek\quad\textrm{ and }\quad\Vert\xkk-\xk\Vert+\Vert\lkk-\lk\Vert\le\bar\tau R_k
\end{equation}
hold. To achieve this goal, set $k=0$, pick $(x^0,\lambda^0)\in\big(\Th\times\R^m\big)\cap\B_{\bar\gamma}(\ox,\olm)$, and observe from  $\bar\gamma\le\gamma'$ that \eqref{c1} holds in this case. We also have $\lambda^0\in\B_{\hat\gg/2\tau}(\olm)$ and $\rho_0\ge \bar\varrho$ and then find by Proposition~\ref{solv} a primal iterate $x^1\in \inte \B_{\hat\gamma}(\ox)$ satisfying $-\nabla_x\L(x^1,\lambda^0,\rho_0)\in N_\Th(x^1)$. Define further 
the multiplier $\lm^1:=\nabla e_{1^{}/\rho_0}g\big(\Phi(x^1)+ \rho_0^{-1}\lambda^0\big)$ and observe that
\begin{equation*}
-\nabla_x L(x^1,\lm^1)=-\nabla_x\L(x^1,\lambda^0,\rho_0)\in N_\Th(x^1).
\end{equation*}
Moreover, employing  Theorem~\ref{est} confirms that 
\begin{equation*}
\Vert x^1-x^0\Vert+\Vert\lm^1-\lambda^0\Vert\le\bar\tau R_0.
\end{equation*}
Thus $(x^1,\lambda^1)$ is well defined and satisfies the claimed condition \eqref{c2} for $k=0$. Assume by induction that the iterates $(\xk,\lk)$, $k=0,1,\ldots,s+1$, are well defined  and that   both conditions \eqref{c1} and \eqref{c2} hold for $k=0,1,\ldots,s$. We verify now the existence of $(x^{s+2},\lambda^{s+2})$ satisfying \eqref{c1} and \eqref{c2} for $k=s+1$. To this end, we first show that $(x^{s+1},\lambda^{s+1})\in\B_{\gamma'}(\ox,\olm)$. 
To proceed, fix an integer   $k$ with $0\le k\le s$.
Since $(\xk,\lk)\in\B_{\gamma'}(\ox,\olm)$, it follows from \eqref{eb1} and \eqref{c1} that
\begin{eqnarray}\label{c3}
R_k&\le&\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\\
&\le&\kappa_2\big(\Vert\xk-\ox\Vert+\Vert\lk-\olm\Vert\big)\le\sqrt{2}\kappa_2\Vert(\xk,\lk)-(\ox,\olm)\Vert\le\sqrt{2}\kappa_2\gamma'.\nonumber
\end{eqnarray}
Combining this with \eqref{c1} and the second relation in \eqref{c2}, we conclude that
\begin{eqnarray}\label{c4}
\Vert(\xkk,\lkk)-(\ox,\olm)\Vert&\le&\Vert\xkk-\xk\Vert+\Vert\lkk-\lk\Vert+\Vert(\xk,\lk)-(\ox,\olm)\Vert\nonumber\\
&\le&\bar\tau R_k+\gamma'\le(\sqrt{2}\bar\tau\kappa_2+1)\gamma'\le\gamma_1,
\end{eqnarray}
which implies that $(\xkk,\lkk)\in\B_{\gamma_1}(\ox,\olm)$. Using \eqref{subr3}, we obtain
\begin{eqnarray}\label{c5}
&&\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\nonumber\\
&\le&\kappa_1 R_{k+1} =\kappa_1\Big(\dist\big(-\nabla_x L(\xkk,\lkk), N_\Th(\xkk)\big) +\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert\Big)\nonumber\\
&\le&\kappa_1\ek+\kappa_1\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert.
\end{eqnarray}
To proceed further,  define
\begin{equation}\label{skk}
\skk:=\proxk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big ).
\end{equation}
It follows from  \eqref{lkk}  and \eqref{ueq19} that
\begin{equation}\label{eq3}
\Phi(\xkk)-\skk= \rho_k^{-1}(\lkk-\lk).
\end{equation}
Since $\lkk=\nabla\menvk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big)$, we deduce from the second equality in \eqref{prm} that 
\begin{equation*}\label{clq17}
\lkk   \in \sub g\big(\Phi(\xkk)+ \rho_k^{-1}(\lk-\lkk)\big)=\partial g(\skk).
\end{equation*} 
Appealing now to the first equality in \eqref{prm} yields $\skk={\rm{prox}}_g(\skk+\lkk)$. Since the mapping $y\mapsto y-{\rm{prox}}_g(y+\lkk)$ is nonexpansive (cf. \cite[Proposition~12.27]{bc}), we arrive at the relationships
\begin{eqnarray}\label{eq2}
&&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert\nonumber\\
&=&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)\big\Vert-\big\Vert\skk-{\rm{prox}}_g(\skk+\lkk)\big\Vert\nonumber\\
&\le&\big\Vert\Phi(\xkk)-{\rm{prox}}_g\big(\Phi(\xkk)+\lkk\big)-\big(\skk-{\rm{prox}}_g(\skk+\lkk)\big)\big\Vert\nonumber\\
&\le&\Vert\Phi(\xkk)-\skk\Vert.
\end{eqnarray}
Combining \eqref{c5}, \eqref{eq3}, and \eqref{eq2} brings us to
\begin{equation*}
\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\le\kappa_1\ek+\rho_k^{-1}{\kappa_1}\Vert\lkk-\lk\Vert.
\end{equation*}
This,  together with \eqref{ek}, \eqref{rhof}, the second inequality in \eqref{c2}, and \eqref{c3} results in 
\begin{eqnarray}\label{c10}
\Vert \xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)&\le&\kappa_1\ek+\dfrac{\bar\tau\kappa_1}{\rok}R_k\le\dfrac{1}{4\kappa_2}R_k +\dfrac{1}{4\kappa_2}R_k\\
&\le&\dfrac{1}{2}\Big(\Vert\xk-\ox\Vert+\dist\big(\lk,\Lambda(\ox)\big)\Big)\nonumber,
\end{eqnarray}
which in turn implies the primal-dual estimates
\begin{equation}\label{c6}
\Vert\xkk-\ox\Vert+\dist\big(\lkk,\Lambda(\ox)\big)\le\dfrac{1}{2^{k+1}}\Big(\Vert x^0-\ox\Vert+\dist\big(\lambda^0,\Lambda(\ox)\big)\Big).
\end{equation}
This estimate, \eqref{c3},  and the second inequality in \eqref{c2} tell us that 
\begin{eqnarray}\label{c7}
\Vert(x^{s+1},\lambda^{s+1})-(x^0,\lambda^0)\Vert&\le&\sum\limits_{k=0}^s\Vert(\xkk,\lkk)-(\xk,\lk)\Vert \le\bar\tau\sum\limits_{k=0}^s R_k\nonumber\\
&\le&\bar\tau\kappa_2\sum\limits_{k=0}^s\Vert\xk-\ox\Vert+\dist\big(\lk,\Lambda(\ox)\big)\nonumber\\
&\le&\bar\tau\kappa_2\sum\limits_{k=0}^s\dfrac{1}{2^k}\Big(\Vert x^0-\ox\Vert+\dist\big(\lambda^0,\Lambda(\ox)\big)\Big)\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\dist(\lambda^0,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\Vert\lambda^0-\olm\Vert\big).\nonumber
\end{eqnarray}
Thus, we arrive at the estimates
\begin{eqnarray*}
\Vert(x^{s+1},\lambda^{s+1})-(\ox,\olm)\Vert&\le&\Vert(x^{s+1},\lambda^{s+1})-(x^0,\lambda^0)\Vert+\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\\
&\le&2\bar\tau\kappa_2\big(\Vert x^0-\ox\Vert+\Vert\lambda^0-\olm\Vert\big)+\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\\
&\le&(2\sqrt{2}\bar\tau\kappa_2+1)\Vert(x^0,\lambda^0)-(\ox,\olm)\Vert\le(2\sqrt{2}\bar\tau\kappa_2+1)\bar\gamma=\gamma',
\end{eqnarray*}
where the last inequality follows from $(x^0,\lambda^0)\in\B_{\bar\gamma}(\ox,\olm)$, while the last equality comes from the definition of $\bar\gamma$ in \eqref{const}. 
This verifies that $(x^{s+1},\lambda^{s+1})\in\B_{\gamma'}(\ox,\olm)$. By  \eqref{const}, we get  $\lambda^{s+1}\in\B_{\hat\gg/2\tau}(\olm)$, and hence Proposition~\ref{solv} ensures the existence of of an optimal solution $x^{s+2}$ 
to \eqref{regp} associated with $(\lm^{s+1},\rho_{s+1})$ such that $x^{s+2}\in \inte\B_{\hat\gamma}(\ox)$. The latter yields 
\begin{equation*}
-\nabla_x\L(x^{s+2},\lambda^{s+1},\rho_{s+1})\in N_\Th(x^{s+2}).
\end{equation*} 
Set now $\lm^{s+2}:=\nabla e_{1^{}/\rho_{s+1}}\big(\Phi(x^{s+2})+\rho_{s+1}^{-1}\lambda^{s+1}\big)$ and observe that
\begin{equation*}
 -\nabla_x L(x^{s+2},\lm^{s+2}) =  -\nabla_x\L(x^{s+2},\lambda^{s+1},\rho_{s+1}) \in N_\Th(x^{s+2}),
\end{equation*}
which by Proposition~\ref{est} brings us to the estimate
\begin{equation*}
\Vert x^{s+2}-x^{s+1}\Vert+\Vert\lm^{s+2}-\lambda^{s+1}\Vert\le\bar\tau R_{s+1}.
\end{equation*}
This tells us that the iterate $(x^{s+2},\lambda^{s+2})$ satisfies   \eqref{c2} for $k=s+1$, which completes  the proof of  induction. Thus there exists a sequence  $\{(\xk,\lk)\c\subset\Th\times\R^m$, generated by Algorithm~\ref{Alg1} 
with $\rok \ge \bar\varrho$ and   $\ek=o\big(R(\xk,\lk)\big)$ for all $k$, for which  \eqref{c1} and \eqref{c2} fulfill.


Next, we are going to justify  the convergence of this primal-dual   sequence. Using the same arguments as in the proofs of \eqref{c6} and \eqref{c7} leads us to
\begin{equation}\label{c8}
\Vert(x^{k+l},\lambda^{k+l})-(\xk,\lk)\Vert\le 2\bar\tau\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\quad\mbox{for all}\;\;k,l\in\N.
\end{equation}
It follows from \eqref{c6} that the right-hand side of \eqref{c8} goes to zero as $k\to\infty$, which tells us that the sequence $\{(\xk,\lk)\c$ is Cauchy. By \eqref{c6},   this sequence converges  to $(\ox,\hat\lambda)$ for some $\hat\lambda\in\Lambda(\ox)$.
Now, we show  that  the rate of this convergence is linear. Indeed, letting $l\to\infty$ in \eqref{c8} tells us that for all $k\in\N$ we have
\begin{equation*}\label{c9}
\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert\le 2\bar\tau\kappa_2\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big),
\end{equation*}
which together with the first inequality in \eqref{c10} verifies that
\begin{eqnarray*}
\Vert(\xkk,\lkk)-(\ox,\hat\lambda)\Vert&\le&2\bar\tau\kappa_2\big(\Vert\xkk-\ox\Vert+\dist(\lkk,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)R_k\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\big(\Vert\xk-\ox\Vert+\dist(\lk,\Lambda(\ox))\big)\nonumber\\
&\le&2\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\big(\Vert\xk-\ox\Vert+\Vert\lk-\hat\lambda\Vert\big)\nonumber\\
&\le& 2\sqrt{2}\bar\tau\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert.
\end{eqnarray*}
Combining this with $\rok\ge \bar\varrho$  with $ \bar\varrho$ taken from \eqref{rhof} and using the choice of the tolerance $\ek=o(R_k)$ result in 
\begin{equation*}
\limsup_{k\to\infty}\dfrac{\Vert(\xkk,\lkk)-(\ox,\hat\lambda)\Vert}{\Vert(\xk,\lk)-(\ox,\hat\lambda)\Vert}\le\limsup_{k\to\infty}2\sqrt{2}\bar\tau
\kappa_1\kappa_2^2\big(R_k^{-1}{\ek}+\rho_k^{-1}\bar\tau\big)\le q.
\end{equation*}
It follows from  $q\in (0,1)$ that the rate of   convergence of $\{(\xk,\lk)\c$ is linear. Furthermore, it is clear from the above inequality that if $\rok\to \infty$, we 
arrive at the superlinear convergence of the latter primal-dual sequence, which completes the proof.
\end{proof}

Given twice continuously differentiable functions   $\ph:\R^n\to \R$ and  $\Phi:\R^n\to \R^m$,  a convex polyhedral set  $\Th$ in $\R^n$, and a convex piecewise linear-quadratic (CPLQ) function $g:\R^m\to \oR$,
 we aim to present a local convergence analysis of the ALM for  the composite optimization problem 
\begin{equation}\label{comp}
\mbox{minimize}\;\;\ph(x)+g\big(\Phi(x)\big)\quad \mbox{subject to}\;\; x\in \Th.
\end{equation}

The augmented Lagrangian $\L:\R^n\times \R^m\times (0,\infty)\to \R$ associated with the composite problem \eqref{comp} is defined  by 
\begin{equation}\label{aug}
\L(x,\lm,\rho):=\ph(x)+e_{ {1}/{\rho}} g \big(\Phi(x)+\rho^{-1}\lm\big)-\sm\rho^{-1}\|\lm\|^2
\end{equation}
with $e_{1/\rho} g$ signifying  the Moreau envelope of   $g$, given  by 
\begin{equation*}\label{Menv}
e_{1/\rho} g(y):=\inf_{z\in \R^m}\big\{g(z)+\frac{\rho}{2}\|y-z\|^2\big\}, \quad y\in \R^m.
\end{equation*}
It is well-known that the augmented Lagrangian $\L$ is continuously differentiable with respect to both $x$ and $\lm$ and is nondecreasing with the respect to $\rho$, the {\em penalty} parameter of the augmented Lagrangian. 
At  each iteration for a given pair $(\lm,\rho)\in \R^m\times (0,\infty)$,  our proposed  ALM for  the  composite problem \eqref{comp}
requires solving the {\em partially} augmented problem 
\begin{equation}\label{augp}
\mini \L(x, \lm, \rho)\quad \mbox{subject to}\;\; x\in \Th.
\end{equation}

A sequence    $\{C^k\b$ of subsets in $\R^n$ is called convergent to a set $C\subset\R^n$ as $k\to \infty$ if $C$ is closed and
\begin{equation*}
\lim_{k\to \infty}{\rm dist}(w,C^k)={\rm dist}(w,C)\;\mbox{ for all }\;w\in\R^n.
\end{equation*}
Given a nonempty set $C\subset\R^n$ with $\ox\in C$, the  tangent cone $T_ C(\ox)$ to $C$ at $\ox$ is defined by
\begin{equation*}\label{2.5}
T_C(\ox)=\big\{w\in\R^n|\;\exists\,t_k{\dn}0,\;\;w_k\to w\;\;\mbox{ as }\;k\to\infty\;\;\mbox{with}\;\;\ox+t_kw_k\in C\big\}.
\end{equation*}
When $C$ is convex, the  {normal cone} to $C$ at $\ox\in C$ in the sense of convex analysis  is given by
\begin{equation*}
N_C(\ox)=\big\{v\in\R^n\;\big|\; \la v,x-\ox\ra\le 0\quad \mbox{for all}\;\; x\in C\big\}.
\end{equation*}
For a convex  function $f:\R^n \to \oR:=(-\infty,\infty]$  with $\ox\in \dom f$, its   subdifferential at $\ox$   is defined  by 
\begin{equation*}\label{sub}
\partial f(\ox)=\big\{v\in\R^n\;\big|\;  \la v,x-\ox\ra\le f(x)-f(\ox)\;\;\mbox{for all}\;x\in \R^n\big\}.
\end{equation*}

A sequence $\{f^k\b$ of functions $f^k:\R^n\to \oR$ is said to {\em epi-converge} to a function $f:\R^n\to [-\infty,\infty]$ if we have $\epi f^k\to \epi f$ as $k\to \infty$.
We denote by $f^k\overset {\ss \mbox{e}}{\to} f$ the  epi-convergence of the sequence $\{f^k\b$ to $f$.
Given  a function  $f:\R^n \to \oR$ and  a point $\ox$ with $f(\ox)$ finite, the subderivative function $\d f(\ox)\colon\R^n\to[-\infty,\infty]$ is defined by
\begin{equation}\label{fsud}
{\mathrm d}f(\ox)(w)=\liminf_{\substack{
   t\dn 0 \\
  w'\to w
  }} {\frac{f(\ox+tw')-f(\ox)}{t}}.
\end{equation}
 The critical cone of $f$ at $\ox$ for $\ov$ with $(\ox,\ov)\in \gph \sub f$ is defined by 
$$
{K_f}(\ox,\ov)=\big\{w\in \R^n\big|\;\la\bar v,w\ra=\d f(\ox)(w)\big\}.
$$
When $f=\dd_C$, namely the indicator function of $C$, the critical cone of $\dd_C$ at $\ox$ for $\ov$ is denoted by $K_C(\ox,\ov)$. In this case, the above definition of the critical cone of a function 
boils down to  the well-known concept of the critical cone of a set (see \cite[page~109]{dr}), namely $K_C(\ox,\ov)=T_C(\ox)\cap [\ov]^\perp$.
Define the parametric  family of 
second-order difference quotients for $f$ at $\ox$ for $\ov\in \R^n$ by 
\begin{equation*}\label{lk01}
\Delta_t^2 f(\bar x , \ov)(w)=\dfrac{f(\ox+tw)-f(\ox)-t\langle \ov,\,w\rangle}{\frac{1}{2}t^2}\quad\quad\mbox{with}\;\;w\in \R^n, \;\;t>0.
\end{equation*}
If $f(\ox)$ is finite, then the {second subderivative} of $f$ at $\ox$ for $\ov$   is given by 
\begin{equation*}\label{ssd}
\d^2 f(\bar x , \ov)(w)= \liminf_{\substack{
   t\dn 0 \\
  w'\to w
  }} \Delta_t^2 f(\ox , \ov)(w'),\;\; w\in \R^n.
\end{equation*}
The second subderivative of $f$ at $\ox$ (without mention of $\ov$) is defined by 
\begin{equation}\label{ssud}
\d^2 f(\ox)(w)=\liminf_{\substack{t\dn 0\\
w'\to w}} \frac{f(\ox+tw')-f(\ox)-t\d f(\ox)(w')}{\sm t^2},\quad w\in \R^n.
\end{equation}
Following \cite[Definition~13.6]{rw}, a function $f:\R^n \to \oR$ is said to be {twice epi-differentiable} at $\bar x$ for $\ov\in\R^n$, with $f(\ox) $ finite, 
if the sets $\epi \Delta_t^2 f(\bar x , \ov)$ converge to $\epi \d^2 f(\bar x,\ov)$ as $t\downarrow 0$. 
In what follows, we refer to the second subderivative of $f$ at $\bar x$ for $\ov$ by the {\em second-order epi-derivative} of $f$ when it is twice epi-differentiable at   $\bar x$ for $\ov$.

Recall  that a function $g:\R^m\to \oR$ is called  piecewise linear-quadratic if $\dom g = \cup_{i=1}^{s} C_i$ with $s\in \N$ and $C_i $ being polyhedral convex  sets for $i = 1, \ldots, s$, and if $g$ has a representation of the form
\begin{equation} \label{PWLQ}
g(z) = \sm \langle A_i z ,z \rangle + \langle a_i ,z \rangle + \alpha_i  \quad \mbox{for all} \quad  z \in C_i,
\end{equation}
where $A_i$ is an $m \times m$ symmetric matrix, $a_i\in \R^m$, and $\alpha_i\in \R$ for all $i = 1, \cdots, s$. Take $\oz\in \dom g$ and define the {\em active} indices  of the domain of $g$ at $\oz$ by
\begin{equation}\label{act}
I(\oz)=\big \{i\in \{1,\ldots, m\} |\, \oz\in C_i\big \}.
\end{equation}
If in addition $g$ is convex, 
it follows   from \cite[page~487]{rw} that 
if  $\oz\in \dom g$, the subdifferential of $g$ at  $\oz$ can be calculated by 
\begin{equation}\label{sub}
\sub g(\oz)=\bigcap_{i\in I(\oz)} \big \{v\in \R^m |\, v-A_i \oz- a_i\in N_{ C_i}(\oz)\big \}.
\end{equation}

The   Karush-Kuhn-Tucker (KKT)   system associated with the composite problem \eqref{comp} is given by 
\begin{equation}\label{vs} 
0\in \nabla_x L(x,\lm)+N_\Th(x),\;\;\lm\in \sub g(\Phi(x)),
\end{equation}
where $L(x,\lm)= \ph(x)+\la \Phi(x),\lm\ra$ for any   $(x,\lm)\in \R^n\times \R^m$. 
Given a point $\ox\in\R^n$, we define the set of {  Lagrange multipliers} of the KKT system \eqref{vs} associated with $\ox$ by
\begin{equation}\label{laset}
\Lambda(\ox):=\big\{\lm\in\R^m\;\big|\; 0\in \nabla_x L(\ox,\lm)+N_\Th(\ox),\;\lm\in \sub g(\Phi(\ox))\big\}.
\end{equation}
If  $(\ox,\olm)$ is a solution to the KKT  system \eqref{vs},   we clearly have   $\olm\in\Lambda(\ox)$.

 Given  a solution $(\ox,\olm)$  to \eqref{vs}, the second-order sufficient condition (SOSC)
for the composite problem \eqref{comp} at $(\ox,\olm)$ is formulated by 
\begin{equation}\label{sosc}
\langle\nabla_{xx}^2L(\bar x,\olm)w,w\rangle+\d^2g (\Phi(\bar x),\olm) (\nabla \Phi(\ox)w )>0\quad \mbox{for all }\; w\in \D\setminus\{0\},
\end{equation}
where the convex cone $\D$ is defined by 
 \begin{equation}\label{coned}
 \D:=K_\Th\big(\ox,-\nabla_x L(\ox,\olm)\big)\cap \big\{w\in \R^n\big|\; \nabla \Phi(\ox)w\in K_g \big(\Phi(\ox),\olm \big)\big\}.
 \end{equation}

a result, obtained recently in \cite{s20}, showing that it yields an error bound estimate for the KKT system \eqref{vs}, which is central to our   local convergence analysis  in this paper. To this end,  recall that, given a constant $r>0$,    the proximal mapping of  a convex function $g:\R^m\to \oR$ is defined by 
\begin{equation*}\label{pr}
{\rm{prox}}_{rg}(x):=\underset{z\in \R^n}{\argmin} \big\{g(z)+\rsm\|x-z\|^2\big\},\quad x\in\R^m.
\end{equation*}
In what follows, when $r=1$, the proximal mapping of $g$ will be denoted by ${\rm{prox}_g}$. For such a convex function, 
it is known that for any $x\in \R^m$ we have 
\begin{equation}\label{prm}
{\rm{prox}}_{rg}(x)=\big(I+r\sub g\big)^{-1}(x) \quad \mbox{and}\quad \nabla e_rg(x)=\big(rI+(\sub g)^{-1}\big)^{-1}(x),
\end{equation}
where $I$ stands for the $m\times m$ identity matrix; see \cite[Proposition~12.19]{rw} and \cite[Theorem~2.26]{rw} for more details.

A function $f:\R^n\to \oR$ is called fully amenable at $\ox\in \dom f$ if there is a neighborhood ${\cal O}$ of $\ox$ on which 
$f$ can be represented in the form $f=\psi\circ h$, where $\psi:\R^m\to \oR$ is a CPLQ function and   $h:\R^n\to \R^m$ is a ${\cal C}^2$ function, and the 
basic constraint qualification 
\begin{equation}\label{bcq}
N_{\ss \dom \psi}\big(h(\ox)\big)\cap \ker \nabla h(\ox)^*=\{0\}
\end{equation}
is satisfied.

Recall that for  the current triple $(\xk, \lk,\rok)\in \R^n\times \R^m\times (0,\infty)$, the next primal iterate $\xkk$ in the ALM is computed as an optimal solution to 
  the subproblem
\begin{equation}\label{conv1}
\mini \L(x, \lk, \rok)\quad \mbox{subject to}\quad x\in \Th.
\end{equation} 
The next dual iterate $\lkk$ is  then calculated as the Lagrange multiplier associated with the optimal solution $\xkk$ to the subproblem \eqref{conv1}, namely  
\begin{equation}\label{lkk}
 \lkk := \nabla\menvk\big(\Phi(\xkk)+ \rho_k^{-1}{\lk}\big).
\end{equation}
 Since an optimal solution  $\xkk$ to the subproblem \eqref{conv1} always satisfies the {\em stationary}  condition
\begin{equation}\label{conv2}
0\in \nabla_x\L(\xkk, \lk, \rok) +N_\Th(\xkk),
\end{equation} 
and since it is often difficult to find an exact solution to \eqref{conv1} in practice, it is more convenient to look for a solution $\xkk$ satisfying the {\em approximate} stationary condition
\begin{equation}\label{xkk}
\dist\big(-\nabla_x\L(\xkk, \lk, \rok),N_\Th(\xkk)\big)\leq \ek,
\end{equation} 
where $\ek\geq 0$ is a   tolerance parameter.

\begin{Algorithm}[augmented Lagrangian method]\label{Alg1}
Choose $(x^0,\lambda^0)\in\Th\times \R^m$ and $\bar\rho>0$. Pick a sequence of tolerance parameters $\{\ek\c$ with $\ek>0$ for all $k$ and $\ek\to   0$ as $k\to\infty$ and a sequence of $\{\rok\c$ such that  $\rok\ge \bar\rho$ for all $k$ and set $k:=0$. Then
\begin{itemize}[noitemsep,topsep=0pt]
\item [{\rm (1)}] if $(\xk,\lk)$ satisfies a suitable termination criterion, stop;
\item[{\rm (2)}]  otherwise, choose  $\xkk$ such that  \eqref{xkk} holds and then update the Lagrange multiplier  $\lkk$ by \eqref{lkk};
\item[{\rm (3)}] set $k\leftarrow k+1$ and go to Step~1.
\end{itemize}
\end{Algorithm}

